    /// The revision-gated decode must leave exactly the state a fresh decode would produce on
    /// every tick: unchanged bags (skipped decode), a watcher change between ticks, and the
    /// armour-stand base-plate yaw that the decode resets and the species tail restitches.
    #[test]
    fn metadata_revision_gated_decode_matches_a_fresh_decode_every_tick() {
        let mut world = World::new();
        let mut tracker = EntityTracker::with_random_seed(17);
        let mut stand_metadata = Metadata::new();
        stand_metadata.set(0, MetadataValue::Byte(0));
        // `EntityArmorStand` index 10: 4 = show arms.
        stand_metadata.set(10, MetadataValue::Byte(4));
        tracker.spawn(
            &mut world,
            5,
            TrackedKind::Type(EntityType::ArmorStand),
            None,
            [0, 64 * 32, 0],
            30.0,
            0.0,
            DVec3::ZERO,
            stand_metadata,
        );
        spawn_at(&mut tracker, &mut world, 6, [64, 64 * 32, 0]);
        let assert_matches_fresh_decode = |tracker: &EntityTracker, world: &World, tick: usize| {
            for id in [5, 6] {
                let tracked = tracker.get(id).unwrap();
                let metadata = world.ecs.get::<&Metadata>(tracked.entity).unwrap();
                assert_eq!(tracked.decoded_metadata_revision, Some(metadata.revision()));
                let mut fresh = tracked.render.entity.clone();
                decode_entity_state(tracked.kind, &metadata, &mut fresh);
                if let (Some(fresh_pose), Some(live_pose)) = (
                    fresh.armor_stand.as_mut(),
                    tracked.render.entity.armor_stand.as_ref(),
                ) {
                    fresh_pose.rotation_yaw = live_pose.rotation_yaw;
                }
                assert_eq!(
                    format!("{fresh:?}"),
                    format!("{:?}", tracked.render.entity),
                    "entity {id} after tick {tick}"
                );
            }
        };
        for tick in 0..6 {
            if tick == 3 {
                let zombie_entity = tracker.get(6).unwrap().entity;
                // Index 0 flag 0x02: sneaking.
                world
                    .ecs
                    .get::<&mut Metadata>(zombie_entity)
                    .unwrap()
                    .set(0, MetadataValue::Byte(2));
                let stand_entity = tracker.get(5).unwrap().entity;
                world
                    .ecs
                    .get::<&mut Metadata>(stand_entity)
                    .unwrap()
                    .set(10, MetadataValue::Byte(0));
            }
            tracker.tick_interpolation(&mut world);
            assert_matches_fresh_decode(&tracker, &world, tick);
        }
        assert!(tracker.get(6).unwrap().render.entity.sneaking);
        let pose = tracker
            .get(5)
            .unwrap()
            .render
            .entity
            .armor_stand
            .as_ref()
            .unwrap();
        assert!(
            !pose.show_arms,
            "the tick-3 watcher change reached the decoded pose"
        );
        assert_eq!(
            pose.rotation_yaw, 30.0,
            "the base-plate yaw is restitched after a skip"
        );
    }

    #[test]
    fn model_state_does_not_retain_non_model_ground_or_water_copies() {
        let model_state = include_str!("../../../mc-render/src/entity/anim.rs");
        assert!(!model_state.contains("pub on_ground: bool"));
        assert!(!model_state.contains("pub in_water: bool"));

        let tracker = include_str!("entities.rs");
        let production = tracker
            .split_once("#[cfg(test)]")
            .expect("entities tests remain isolated")
            .0;
        assert!(!production.contains("render.entity.on_ground"));
        assert!(!production.contains("render.entity.in_water"));
        assert!(production.contains("let on_ground = tracked.on_ground;"));
        // The species tick still probes the world itself, now only for the
        // species that read the result.
        assert!(production.contains("let in_water = reads_water && in_water(world, tracked);"));
    }

    /// `EntityPlayer.trySleep` is a player-only, generation-owned transition.  The four
    /// horizontal metadata values exercise both the feet placement and RenderPlayer's separate
    /// ±1.8 draw offset; waking must restore the ordinary box and safe-exit position, while an
    /// ordinary mob and a replacement generation remain upright.
    #[test]
    fn remote_player_sleep_faces_all_beds_wakes_and_does_not_follow_id_reuse() {
        let mut world = World::new();
        let chunk = ChunkPos::new(0, 0);
        world.load_empty_chunk(chunk);
        let bed = BlockPos::new(8, 65, 8);
        let stone = BlockState::new(block_by_name("stone").expect("stone"), 0);
        // Make the first safe-exit candidate (7, 7) valid, and keep the entire scan deterministic.
        for x in 7..=9 {
            for z in 7..=9 {
                world.set_block(BlockPos::new(x, 64, z), stone);
            }
        }
        let mut tracker = EntityTracker::new();
        let _player = tracker.spawn(
            &mut world,
            44,
            TrackedKind::Player,
            Some(Uuid::from_u128(44)),
            [8 * 32, 70 * 32, 8 * 32],
            37.0,
            4.0,
            DVec3::ZERO,
            Metadata::new(),
        );
        let mob = tracker.spawn(
            &mut world,
            45,
            zombie(),
            None,
            [8 * 32, 70 * 32, 8 * 32],
            0.0,
            0.0,
            DVec3::ZERO,
            Metadata::new(),
        );
        let expected = [
            // metadata 0..=3 is S-W-N-E, matching EnumFacing.HORIZONTALS.
            (DVec3::new(8.5, 65.6875, 8.9), DVec3::new(0.0, 0.0, -1.8)),
            (DVec3::new(8.1, 65.6875, 8.5), DVec3::new(1.8, 0.0, 0.0)),
            (DVec3::new(8.5, 65.6875, 8.1), DVec3::new(0.0, 0.0, 1.8)),
            (DVec3::new(8.9, 65.6875, 8.5), DVec3::new(-1.8, 0.0, 0.0)),
        ];
        for (meta, (position, render_offset)) in expected.into_iter().enumerate() {
            world.set_block(
                bed,
                BlockState::new(BlockState::from_raw(26 << 4).block(), meta as u8),
            );
            assert!(tracker.enter_bed(&mut world, 44, bed), "metadata {meta}");
            let tracked = tracker.get(44).expect("player remains tracked");
            assert!(tracked.sleeping);
            assert_eq!(tracked.sleeping_at, Some(bed));
            assert_eq!(tracked.render_offset, render_offset);
            assert_eq!(tracked.dimensions(), (0.2, 0.2));
            assert_eq!(
                world.ecs.get::<&Position>(tracked.entity).unwrap().0,
                position,
                "metadata {meta} feet position"
            );
            assert_eq!(tracked.target_pos, position);
            assert_eq!(tracked.interpolation_steps, 0);

            assert!(
                !tracker.enter_bed(&mut world, 45, bed),
                "mob accepted player sleep"
            );
            assert_eq!(
                world.ecs.get::<&Position>(mob).unwrap().0,
                DVec3::new(8.0, 70.0, 8.0),
                "non-player position changed"
            );

            assert!(
                tracker.wake_from_bed(&mut world, 44),
                "metadata {meta} wake"
            );
            let tracked = tracker.get(44).unwrap();
            assert!(!tracked.sleeping);
            assert_eq!(tracked.render_offset, DVec3::ZERO);
            assert_eq!(tracked.dimensions(), (0.6, 1.8));
            assert_eq!(
                world.ecs.get::<&Position>(tracked.entity).unwrap().0,
                DVec3::new(7.5, 65.1f32 as f64, 7.5),
                "metadata {meta} safe exit"
            );
        }

        let old_player = tracker.get(44).unwrap().entity;
        assert!(tracker.despawn(&mut world, 44));
        let replacement = tracker.spawn(
            &mut world,
            44,
            zombie(),
            None,
            [8 * 32, 70 * 32, 8 * 32],
            0.0,
            0.0,
            DVec3::ZERO,
            Metadata::new(),
        );
        assert_ne!(
            replacement, old_player,
            "id reuse must create a fresh ECS generation"
        );
        assert!(!tracker.get(44).unwrap().sleeping);
        assert!(
            !tracker.enter_bed(&mut world, 44, bed),
            "zombie replacement slept"
        );
    }

    #[test]
    fn collision_candidates_snapshot_boats_in_tracker_order_and_leave_minecarts_null() {
        let mut world = World::new();
        let mut tracker = EntityTracker::new();
        tracker.spawn(
            &mut world,
            11,
            TrackedKind::Type(EntityType::Boat),
            None,
            [2 * 32, 64 * 32, 4 * 32],
            0.0,
            0.0,
            DVec3::ZERO,
            Metadata::new(),
        );
        tracker.spawn(
            &mut world,
            12,
            TrackedKind::Type(EntityType::MinecartRideable),
            None,
            [5 * 32, 64 * 32, 4 * 32],
            0.0,
            0.0,
            DVec3::ZERO,
            Metadata::new(),
        );

        let candidates = tracker.collision_candidates(&world, -1, &PlayerList::new());
        assert_eq!(
            candidates.len(),
            2,
            "both loaded entities remain query candidates"
        );

        let boat = Aabb::from_bounds(
            1.25,
            64.0,
            3.25,
            2.75,
            64.0 + f64::from(EntityType::Boat.info().height),
            4.75,
        );
        assert_eq!(candidates[0].query_box, boat);
        assert_eq!(candidates[0].collision_box, Some(boat));
        assert_eq!(
            candidates[1].collision_box, None,
            "EntityMinecart.getCollisionBoundingBox() is Java null"
        );
        assert_eq!(
            candidates[0].query_box.min.x, 1.25,
            "insertion order keeps the boat before the later minecart"
        );
    }

    #[test]
    fn collision_candidates_follow_java_chunk_x_z_then_y_bucket_order() {
        let mut world = World::new();
        let mut tracker = EntityTracker::new();
        // Insert the positive column first to make a global insertion walk disagree with
        // World.getEntitiesInAABBexcluding's chunk traversal. The negative column must still
        // come first, and a second entity in that column must follow its lower Y slice.
        for (id, x, y) in [(1, 16.0, 32.0), (2, -16.0, 16.0), (3, -16.0, 0.0)] {
            tracker.spawn(
                &mut world,
                id,
                TrackedKind::Type(EntityType::Boat),
                None,
                [
                    (x * FIXED_POINT_SCALE) as i32,
                    (y * FIXED_POINT_SCALE) as i32,
                    0,
                ],
                0.0,
                0.0,
                DVec3::ZERO,
                Metadata::new(),
            );
        }

        let candidates = tracker.collision_candidates(&world, -1, &PlayerList::new());
        assert_eq!(candidates.len(), 3);
        assert_eq!(candidates[0].query_box.min.y, 0.0);
        assert_eq!(candidates[1].query_box.min.y, 16.0);
        assert_eq!(candidates[2].query_box.min.x, 15.25);
        // The two negative-column boats are ordered by their clamped Chunk.entityLists slice,
        // not by the packet insertion order (id 2 was inserted before id 3).
        assert_eq!(candidates[0].query_box.min.x, -16.75);
        assert_eq!(candidates[1].query_box.min.x, -16.75);
    }

    #[test]
    fn packet_spawn_waits_for_resident_chunk_and_reload_reuses_the_same_generation() {
        let mut world = World::new();
        let mut tracker = EntityTracker::new();
        let chunk = ChunkPos::new(2, -3);
        let entity = tracker.spawn_packet(
            &mut world,
            70,
            zombie(),
            None,
            [
                chunk.x * 16 * 32 + 4 * 32,
                64 * 32,
                chunk.z * 16 * 32 + 4 * 32,
            ],
            0.0,
            0.0,
            DVec3::ZERO,
            Metadata::new(),
        );
        assert!(
            tracker.get(70).is_some(),
            "the id map retains pending objects"
        );
        assert!(!tracker.is_resident(70));
        assert!(tracker.iter().next().is_none());
        assert_eq!(tracker.pending_spawn_count(), 1);

        world.load_empty_chunk(chunk);
        assert_eq!(tracker.activate_chunk(&world, chunk), vec![70]);
        assert!(tracker.is_resident(70));
        assert_eq!(
            tracker.iter().map(|(id, _)| id).collect::<Vec<_>>(),
            vec![70]
        );

        // Chunk unload parks, rather than destroys, the Java entity object. Reload admits the
        // same ECS handle; this is the negative control against a fresh-spawn-on-reload bug.
        assert_eq!(tracker.unload_in_chunk(&world, chunk), vec![70]);
        assert!(!tracker.is_resident(70));
        assert_eq!(tracker.pending_spawn_count(), 1);
        world.unload_chunk(chunk);
        world.load_empty_chunk(chunk);
        assert_eq!(tracker.activate_chunk(&world, chunk), vec![70]);
        assert_eq!(tracker.get(70).expect("reloaded entity").entity, entity);
    }

    /// Several stale buckets: moved ids leave their bucket in bucket order, the rest stay in
    /// order, and emptied buckets disappear, matching the former remove/re-insert re-keying.
    #[test]
    fn activate_chunk_rekeys_several_stale_buckets_in_place() {
        let mut world = World::new();
        let mut tracker = EntityTracker::new();
        let mut entities = Vec::new();
        for (id, chunk_x) in [(1, 5), (2, 5), (3, 5), (4, 6), (5, 6)] {
            entities.push(tracker.spawn_packet(
                &mut world,
                id,
                TrackedKind::Type(EntityType::Item),
                None,
                [chunk_x * 16 * 32 + 8 * 32, 70 * 32, 8 * 32],
                0.0,
                0.0,
                DVec3::ZERO,
                Metadata::new(),
            ));
        }
        assert_eq!(tracker.pending_spawn_count(), 5);
        let target = ChunkPos::new(0, 0);
        let move_into_target = |world: &mut World, entity: Entity, x: f64| {
            world.ecs.get::<&mut Position>(entity).unwrap().0 = DVec3::new(x, 70.0, 8.0);
        };
        move_into_target(&mut world, entities[2], 3.0);
        move_into_target(&mut world, entities[1], 5.0);
        world.load_empty_chunk(target);
        assert_eq!(tracker.activate_chunk(&world, target), vec![2, 3]);
        assert_eq!(
            tracker.pending_by_chunk.get(&ChunkPos::new(5, 0)),
            Some(&vec![1])
        );
        assert_eq!(
            tracker.pending_by_chunk.get(&ChunkPos::new(6, 0)),
            Some(&vec![4, 5])
        );

        move_into_target(&mut world, entities[4], 9.0);
        move_into_target(&mut world, entities[0], 11.0);
        let activated = tracker.activate_chunk(&world, target);
        assert_eq!(activated.len(), 2);
        assert!(activated.contains(&1) && activated.contains(&5));
        assert_eq!(tracker.pending_by_chunk.get(&ChunkPos::new(5, 0)), None);
        assert_eq!(
            tracker.pending_by_chunk.get(&ChunkPos::new(6, 0)),
            Some(&vec![4])
        );
        assert_eq!(tracker.pending_spawn_count(), 1);
        assert_eq!(&tracker.iteration_order[..2], &[2, 3]);
    }

    #[test]
    fn pending_movement_rekeys_to_the_latest_chunk_and_id_reuse_drops_the_tombstone() {
        let mut world = World::new();
        let mut tracker = EntityTracker::new();
        let old = tracker.spawn_packet(
            &mut world,
            71,
            TrackedKind::Player,
            Some(Uuid::from_u128(71)),
            [33 * 32, 70 * 32, 0],
            0.0,
            0.0,
            DVec3::ZERO,
            Metadata::new(),
        );
        assert!(!tracker.is_resident(71));
        tracker.apply_teleport(&mut world, 71, [17 * 32, 70 * 32, 0], 0.0, 0.0);
        let latest_chunk = ChunkPos::new(1, 0);
        world.load_empty_chunk(latest_chunk);
        // A pending remote player retains its current ECS position while the teleport target is
        // interpolated. Java retries the current `posX/Y/Z`, not the target interpolation point,
        // so loading the target chunk alone must not admit it early.
        assert!(tracker.activate_chunk(&world, latest_chunk).is_empty());
        assert!(!tracker.is_resident(71));

        let original_chunk = ChunkPos::new(2, 0);
        world.load_empty_chunk(original_chunk);
        assert_eq!(tracker.activate_chunk(&world, original_chunk), vec![71]);
        assert!(tracker.is_resident(71));

        // A replacement id must remove the queued old generation and its ECS handle before the
        // new packet is admitted. Without this tombstone cleanup, a later retry can resurrect the
        // old player after the id has already been reused.
        tracker.unload_in_chunk(&world, original_chunk);
        let replacement = tracker.spawn_packet(
            &mut world,
            71,
            zombie(),
            None,
            [17 * 32, 70 * 32, 0],
            0.0,
            0.0,
            DVec3::ZERO,
            Metadata::new(),
        );
        assert_ne!(replacement, old);
        assert_eq!(tracker.pending_spawn_count(), 0);
        assert!(world.ecs.get::<&Position>(old).is_err());
        assert!(tracker.is_resident(71));
        assert_eq!(
            tracker.iter().map(|(id, _)| id).collect::<Vec<_>>(),
            vec![71]
        );
    }

    #[test]
    fn generic_fire_tail_matches_java_dry_wet_and_nonflammable_controls() {
        let fire = BlockState::new(block_by_name("fire").expect("fire"), 0);
        let water = BlockState::new(block_by_name("water").expect("water"), 0);
        let section = ChunkPos::new(0, 0);

        // A boat is a client-live mover with a width large enough to overlap both cells below.
        // Dry fire increments the post-base-reset counter once; it does not set eight seconds on
        // every tick (that setter is only the Java int-overflow guard).
        let mut dry_world = World::new();
        dry_world.load_empty_chunk(section);
        dry_world.set_block(BlockPos::new(0, 64, 0), fire);
        let mut dry_tracker = EntityTracker::new();
        dry_tracker.spawn(
            &mut dry_world,
            81,
            TrackedKind::Type(EntityType::Boat),
            None,
            [16, 64 * 32, 16],
            0.0,
            0.0,
            DVec3::ZERO,
            Metadata::new(),
        );
        let dry = dry_tracker.by_network_id.get_mut(&81).expect("dry boat");
        advance_generic_entity_base_tick(&dry_world, dry);
        let mut dry_events = Vec::new();
        advance_generic_entity_fire_tail(&dry_world, dry, false, &mut dry_events);
        assert_eq!(dry.fire, 1);
        assert!(dry_events.is_empty());

        // Water suppresses the dry increment. Since the inherited remote base tick reset fire to
        // zero, this also proves the fizz branch does not invent a sound without a positive timer.
        let mut wet_world = World::new();
        wet_world.load_empty_chunk(section);
        wet_world.set_block(BlockPos::new(0, 64, 0), water);
        wet_world.set_block(BlockPos::new(1, 64, 0), fire);
        let mut wet_tracker = EntityTracker::new();
        wet_tracker.spawn(
            &mut wet_world,
            82,
            TrackedKind::Type(EntityType::Boat),
            None,
            [16, 64 * 32, 16],
            0.0,
            0.0,
            DVec3::ZERO,
            Metadata::new(),
        );
        let wet = wet_tracker.by_network_id.get_mut(&82).expect("wet boat");
        advance_generic_entity_base_tick(&wet_world, wet);
        assert!(wet.in_water, "the water cell overlaps the boat's live AABB");
        let mut wet_events = Vec::new();
        advance_generic_entity_fire_tail(&wet_world, wet, false, &mut wet_events);
        assert_eq!(wet.fire, 0);
        assert!(wet_events.is_empty());

        // Air is the non-flammable negative control: Java stores the mover's default
        // fire-resistance sentinel, rather than a positive burning timer.
        let mut clear_world = World::new();
        clear_world.load_empty_chunk(section);
        let mut clear_tracker = EntityTracker::new();
        clear_tracker.spawn(
            &mut clear_world,
            83,
            TrackedKind::Type(EntityType::Boat),
            None,
            [16, 64 * 32, 16],
            0.0,
            0.0,
            DVec3::ZERO,
            Metadata::new(),
        );
        let clear = clear_tracker
            .by_network_id
            .get_mut(&83)
            .expect("clear boat");
        advance_generic_entity_base_tick(&clear_world, clear);
        let mut clear_events = Vec::new();
        advance_generic_entity_fire_tail(&clear_world, clear, false, &mut clear_events);
        assert_eq!(clear.fire, -1);
        assert!(clear_events.is_empty());
    }

