    /// `NetHandlerPlayClient.handleEntityVelocity` calls `setVelocity` for the entity id it
    /// resolves (`NetHandlerPlayClient.java:501-509`); a remote throwable then consumes that
    /// motion in `EntityThrowable.onUpdate` (`EntityThrowable.java:143-286`).  The local player
    /// is deliberately not an `EntityTracker` entry, so its id must remain for the session-owned
    /// predictor rather than being accidentally treated as a remote entity here.
    #[test]
    fn s12_velocity_reaches_remote_throwable_but_not_session_owned_local_player() {
        let mut world = World::new();
        let mut tracker = EntityTracker::new();
        let remote = tracker.spawn(
            &mut world,
            11,
            TrackedKind::Type(EntityType::ThrownEgg),
            None,
            [0, 64 * 32, 0],
            0.0,
            0.0,
            DVec3::ZERO,
            Metadata::new(),
        );

        // A local player's network id is resolved by the session before it reaches this tracker;
        // an unknown id must not create or mutate a remote ECS entity as a fallback.
        let local_player_id = 700;
        assert!(!tracker.apply_velocity(&mut world, local_player_id, [4000, 0, 0]));
        assert!(tracker.get(local_player_id).is_none());
        assert_eq!(tracker.len(), 1);

        assert!(tracker.apply_velocity(&mut world, 11, [4000, 0, 0]));
        tracker.tick_interpolation(&mut world);

        assert_eq!(
            world.ecs.get::<&Position>(remote).unwrap().0,
            DVec3::new(0.5, 64.0, 0.0),
            "the nonlocal S12 motion must be consumed by EntityThrowable's live tick"
        );
        let velocity = world.ecs.get::<&Velocity>(remote).unwrap().0;
        assert_eq!(
            velocity.x.to_bits(),
            (0.5_f64 * f64::from(0.99_f32)).to_bits()
        );
        assert_eq!(velocity.y.to_bits(), (-f64::from(0.03_f32)).to_bits());
    }

    /// The other direct-motion object subclasses are also client-ticked after S12.  This is a
    /// cause-level control: removing either live consumer leaves its position at the packet
    /// coordinate even though `apply_velocity` still reports success.
    #[test]
    fn firework_motion_constructor_matches_java_and_reaches_zero_data_spawn() {
        let seed = 0x5eed;
        let mut actual_random = JavaRandom::new(seed);
        let actual = firework_constructor_motion(&mut actual_random);
        let mut expected_random = JavaRandom::new(seed);
        let expected = DVec3::new(
            expected_random.next_gaussian() * 0.001,
            0.05,
            expected_random.next_gaussian() * 0.001,
        );
        assert_eq!(actual.x.to_bits(), expected.x.to_bits());
        assert_eq!(actual.y.to_bits(), expected.y.to_bits());
        assert_eq!(actual.z.to_bits(), expected.z.to_bits());

        let mut world = World::new();
        let mut tracker = EntityTracker::new();
        let rocket = tracker.spawn(
            &mut world,
            75,
            TrackedKind::Type(EntityType::FireworksRocketEntity),
            None,
            [0, 64 * 32, 0],
            0.0,
            0.0,
            DVec3::ZERO,
            Metadata::new(),
        );
        let spawned = world.ecs.get::<&Velocity>(rocket).unwrap().0;
        assert_eq!(spawned.y.to_bits(), 0.05_f64.to_bits());
        assert!(spawned.x != 0.0 || spawned.z != 0.0);
    }

