    #[test]
    fn ender_crystal_tick_places_fire_only_in_the_end_at_the_floored_current_position() {
        let target = BlockPos::new(-1, 64, 2);
        let fire = BlockState::new(block_by_name("fire").unwrap(), 0);
        let stone = BlockState::new(block_by_name("stone").unwrap(), 0);

        for initial in [BlockState::AIR, stone] {
            let mut world = World::new();
            world.load_empty_chunk(target.chunk_pos());
            world.set_block(target, initial);
            world.drain_dirty_sections();
            let mut tracker = EntityTracker::new();
            tracker.spawn(
                &mut world,
                81,
                TrackedKind::Type(EntityType::EnderCrystal),
                None,
                [-1, 64 * 32, 65],
                0.0,
                0.0,
                DVec3::ZERO,
                Metadata::new(),
            );

            tracker.tick_interpolation_with_local_player_in_dimension(
                &mut world,
                None,
                &PlayerList::new(),
                1,
            );

            assert_eq!(world.block_at(target), fire);
            assert!(world
                .dirty_sections()
                .any(|section| section == target.section_pos()));

            // A server correction owns the intervening state; the next vanilla crystal tick
            // deliberately restores fire over any non-fire block, including End stone/stone.
            world.set_block(target, stone);
            assert_eq!(world.block_at(target), stone);
            tracker.tick_interpolation_with_local_player_in_dimension(
                &mut world,
                None,
                &PlayerList::new(),
                1,
            );
            assert_eq!(world.block_at(target), fire);
        }

        for dimension in [-1, 0] {
            let mut world = World::new();
            world.load_empty_chunk(target.chunk_pos());
            world.set_block(target, stone);
            let mut tracker = EntityTracker::new();
            tracker.spawn(
                &mut world,
                82,
                TrackedKind::Type(EntityType::EnderCrystal),
                None,
                [-1, 64 * 32, 65],
                0.0,
                0.0,
                DVec3::ZERO,
                Metadata::new(),
            );

            tracker.tick_interpolation_with_local_player_in_dimension(
                &mut world,
                None,
                &PlayerList::new(),
                dimension,
            );
            assert_eq!(world.block_at(target), stone);
        }

        let mut world = World::new();
        world.load_empty_chunk(target.chunk_pos());
        world.set_block(target, fire);
        world.drain_dirty_sections();
        let mut tracker = EntityTracker::new();
        tracker.spawn(
            &mut world,
            83,
            TrackedKind::Type(EntityType::EnderCrystal),
            None,
            [-1, 64 * 32, 65],
            0.0,
            0.0,
            DVec3::ZERO,
            Metadata::new(),
        );
        tracker.tick_interpolation_with_local_player_in_dimension(
            &mut world,
            None,
            &PlayerList::new(),
            1,
        );
        assert_eq!(world.block_at(target), fire);
        assert_eq!(world.dirty_sections().count(), 0);
    }

    #[test]
    fn firework_constructor_rng_precedes_wire_velocity_and_trail_rng() {
        let kind = TrackedKind::Type(EntityType::FireworksRocketEntity);
        for wire_velocity in [DVec3::ZERO, DVec3::new(0.25, -0.5, 0.75)] {
            let seed = 0xF17E;
            let mut actual_random = JavaRandom::new(seed);
            let actual = constructor_velocity(kind, wire_velocity, &mut actual_random);

            let mut expected_random = JavaRandom::new(seed);
            let constructor_motion = DVec3::new(
                expected_random.next_gaussian() * 0.001,
                0.05,
                expected_random.next_gaussian() * 0.001,
            );
            let _lifetime = expected_random.next_i32_bound(6) + expected_random.next_i32_bound(7);
            let expected = if wire_velocity == DVec3::ZERO {
                constructor_motion
            } else {
                wire_velocity
            };

            assert_eq!(actual, expected);
            assert_eq!(actual_random.raw_seed(), expected_random.raw_seed());
        }

        let mut ordinary_random = JavaRandom::new(0xF17E);
        let untouched_seed = ordinary_random.raw_seed();
        let ordinary_velocity = DVec3::new(1.0, 2.0, 3.0);
        assert_eq!(
            constructor_velocity(
                TrackedKind::Type(EntityType::Snowball),
                ordinary_velocity,
                &mut ordinary_random
            ),
            ordinary_velocity
        );
        assert_eq!(ordinary_random.raw_seed(), untouched_seed);
    }

    #[test]
    fn primed_tnt_constructor_motion_matches_java_angle_narrowing_and_draw_order() {
        let kind = TrackedKind::Type(EntityType::PrimedTnt);
        let seed = 0x7_17A;
        let mut actual_random = JavaRandom::new(seed);
        let actual = constructor_velocity(kind, DVec3::ZERO, &mut actual_random);

        let mut expected_random = JavaRandom::new(seed);
        let angle = (expected_random.next_f64() * core::f64::consts::PI * 2.0) as f32;
        let expected = DVec3::new(
            f64::from(-(f64::from(angle).sin() as f32) * 0.02_f32),
            0.200_000_002_980_232_24,
            f64::from(-(f64::from(angle).cos() as f32) * 0.02_f32),
        );

        assert_eq!(actual.x.to_bits(), expected.x.to_bits());
        assert_eq!(actual.y.to_bits(), expected.y.to_bits());
        assert_eq!(actual.z.to_bits(), expected.z.to_bits());
        let horizontal_magnitude = (actual.x * actual.x + actual.z * actual.z).sqrt();
        assert!(
            (horizontal_magnitude - 0.02).abs() < 1.0e-7,
            "the constructor launch vector is horizontal with Java's 0.02F magnitude: {horizontal_magnitude:?}"
        );
        assert_eq!(
            actual_random.raw_seed(),
            expected_random.raw_seed(),
            "the angle consumes exactly one Java nextDouble"
        );
    }

