    /// Java's `Entity.setPositionAndRotation2` for the base (non-living) class calls
    /// `setRotation`, so a snapped item receives Java's truncating `% 360` remainder.  Living
    /// entities retain the raw wire angles in their three-tick target fields.
    #[test]
    fn non_living_snap_lifts_from_blocks_and_wraps_only_its_rotation() {
        let mut world =
            mc_physics::scene::flat(BlockState::new(block_by_name("stone").unwrap(), 0), 0, 2);
        let mut tracker = EntityTracker::new();
        let item = tracker.spawn(
            &mut world,
            1,
            TrackedKind::Type(EntityType::Item),
            None,
            [0, 4 * 32, 0],
            0.0,
            0.0,
            DVec3::ZERO,
            Metadata::new(),
        );
        let zombie = tracker.spawn(
            &mut world,
            2,
            zombie(),
            None,
            [0, 4 * 32, 0],
            0.0,
            0.0,
            DVec3::ZERO,
            Metadata::new(),
        );

        assert!(tracker.apply_teleport(&mut world, 1, [0, 0, 0], 725.0, -725.0));
        let item_position = world.ecs.get::<&Position>(item).unwrap().0;
        assert_eq!(item_position, DVec3::new(0.0, 1.0, 0.0));
        let item_rotation = *world.ecs.get::<&Rotation>(item).unwrap();
        assert_eq!(item_rotation.yaw, 5.0);
        assert_eq!(item_rotation.pitch, -5.0);

        assert!(tracker.apply_teleport(&mut world, 2, [0, 0, 0], 725.0, -725.0));
        let tracked = tracker.get(2).unwrap();
        assert_eq!(tracked.target_yaw, 725.0);
        assert_eq!(tracked.target_pitch, -725.0);
        assert_eq!(
            world.ecs.get::<&Rotation>(zombie).unwrap().yaw,
            0.0,
            "living target angles are not applied until the interpolation tick"
        );
    }

    /// `EntityArrow.setPositionAndRotation2` (`EntityArrow.java:148-152`, `javap -c
    /// wq.a(DDDFFIZ)V`) overrides the base snap with `setPosition` + `setRotation` only, so an
    /// arrow the tracker re-sends while it is stuck in a wall stays in the wall. The snowball,
    /// teleported to an equivalent overlap with its own stone block, is the control: it inherits
    /// `Entity.setPositionAndRotation2`'s lift (`Entity.java:2013-2033`), which the arrow used to
    /// take as well, popping every wall-stuck arrow onto the top of its block.
    #[test]
    fn arrow_snap_skips_the_base_collision_lift_that_a_throwable_takes() {
        let mut world = resident_test_world();
        let stone = BlockState::new(block_by_name("stone").unwrap(), 0);
        world.set_block(BlockPos::new(1, 64, 0), stone);
        world.set_block(BlockPos::new(1, 64, 5), stone);
        let mut tracker = EntityTracker::new();
        let arrow = tracker.spawn(
            &mut world,
            60,
            TrackedKind::Type(EntityType::Arrow),
            None,
            [0, 70 * 32, 16],
            0.0,
            0.0,
            DVec3::ZERO,
            Metadata::new(),
        );
        let snowball = tracker.spawn(
            &mut world,
            61,
            TrackedKind::Type(EntityType::Snowball),
            None,
            [0, 70 * 32, 5 * 32 + 16],
            0.0,
            0.0,
            DVec3::ZERO,
            Metadata::new(),
        );

        // x = 30/32: the arrow's 0.5-wide box (less the lift's 1/32 contraction) and the
        // snowball's 0.25-wide one both reach into the stone at x = 1.
        assert!(tracker.apply_teleport(&mut world, 60, [30, 64 * 32 + 8, 16], 90.0, 0.0));
        assert!(tracker.apply_teleport(&mut world, 61, [30, 64 * 32 + 8, 5 * 32 + 16], 90.0, 0.0));

        assert_eq!(
            world.ecs.get::<&Position>(snowball).unwrap().0,
            DVec3::new(0.9375, 65.0, 5.5),
            "the base snap lifts a throwable onto the block it overlaps"
        );
        assert_eq!(
            world.ecs.get::<&Position>(arrow).unwrap().0,
            DVec3::new(0.9375, 64.25, 0.5),
            "EntityArrow's override keeps the packet position inside the block"
        );
        assert_eq!(world.ecs.get::<&Rotation>(arrow).unwrap().yaw, 90.0);
    }

    /// `EntityThrowable`'s water branch comes after translation, produces four bubbles with the
    /// old motion and replaces its ordinary 0.99F drag with 0.8F before potion gravity. The
    /// branch reads `isInWater()`, the latch `handleWaterMovement` set from the *pre-move* box
    /// (`javap -c wy.t_()` offset 898 -> `pk.V()`, `getfield Y`), so the two potions here are
    /// reciprocal controls: one leaving a water cell still takes the water tick, one entering a
    /// water cell does not yet. This test used to move a potion *into* water and expect the water
    /// tick at once, which was the post-move probe bug.
    #[test]
    fn thrown_potion_water_tick_uses_old_motion_for_bubbles_and_water_drag() {
        let mut world = resident_test_world();
        let water = BlockState::new(block_by_name("water").unwrap(), 0);
        world.set_block(BlockPos::new(0, 64, 0), water);
        world.set_block(BlockPos::new(11, 64, 0), water);
        let mut tracker = EntityTracker::new();
        let potion = tracker.spawn(
            &mut world,
            73,
            TrackedKind::Type(EntityType::ThrownPotion),
            None,
            [16, 64 * 32, 16],
            0.0,
            0.0,
            DVec3::new(1.0, 0.0, 0.0),
            Metadata::new(),
        );
        world
            .ecs
            .insert_one(potion, mc_world::SplashPotionDamage(16_384))
            .unwrap();
        let entering_potion = tracker.spawn(
            &mut world,
            74,
            TrackedKind::Type(EntityType::ThrownPotion),
            None,
            [10 * 32 + 16, 64 * 32, 16],
            0.0,
            0.0,
            DVec3::new(1.0, 0.0, 0.0),
            Metadata::new(),
        );
        world
            .ecs
            .insert_one(entering_potion, mc_world::SplashPotionDamage(16_384))
            .unwrap();

        tracker.tick_interpolation(&mut world);

        let velocity = world.ecs.get::<&Velocity>(potion).unwrap().0;
        assert_eq!(velocity.x.to_bits(), f64::from(0.8_f32).to_bits());
        assert_eq!(velocity.y.to_bits(), (-f64::from(0.05_f32)).to_bits());
        assert_eq!(
            world.ecs.get::<&Position>(entering_potion).unwrap().0,
            DVec3::new(11.5, 64.0, 0.5)
        );
        let entering_velocity = world.ecs.get::<&Velocity>(entering_potion).unwrap().0;
        assert_eq!(
            entering_velocity.x.to_bits(),
            f64::from(0.99_f32).to_bits(),
            "a potion that has only just moved into water keeps the air drag this tick"
        );
        assert_eq!(
            entering_velocity.y.to_bits(),
            (-f64::from(0.05_f32)).to_bits(),
            "the entering control still applies potion gravity"
        );
        let bubbles = tracker.take_particle_events();
        assert_eq!(bubbles.len(), 4, "only the potion that started wet bubbles");
        for bubble in bubbles {
            assert_eq!(bubble.particle_id, WATER_BUBBLE);
            assert_eq!(bubble.position, DVec3::new(1.25, 64.0, 0.5));
            assert_eq!(bubble.velocity, DVec3::new(1.0, 0.0, 0.0));
        }
    }

    /// `arrowShake` is constructor-local state, not a status or watched value. The arrow's
    /// local block-collision tick sets it on impact; after that, each ordinary entity tick
    /// decrements exactly once. A sibling projectile must not acquire the component or decay.
    #[test]
    fn arrow_shake_starts_at_zero_ticks_after_an_impact_and_ignores_status_packets() {
        let mut world = World::new();
        let mut tracker = EntityTracker::new();
        let arrow = tracker.spawn(
            &mut world,
            1,
            TrackedKind::Type(EntityType::Arrow),
            None,
            [0, 0, 0],
            0.0,
            0.0,
            DVec3::ZERO,
            Metadata::new(),
        );
        let snowball = tracker.spawn(
            &mut world,
            2,
            TrackedKind::Type(EntityType::Snowball),
            None,
            [0, 0, 0],
            0.0,
            0.0,
            DVec3::ZERO,
            Metadata::new(),
        );

        assert_eq!(*world.ecs.get::<&ArrowShake>(arrow).unwrap(), ArrowShake(0));
        assert!(world.ecs.get::<&ArrowShake>(snowball).is_err());
        world
            .ecs
            .get::<&mut ArrowShake>(arrow)
            .unwrap()
            .on_block_impact();
        assert_eq!(*world.ecs.get::<&ArrowShake>(arrow).unwrap(), ArrowShake(7));

        // `EntityArrow` has no `handleStatusUpdate` override and `Entity`'s inherited method is
        // empty, so status 2 is deliberately unhandled; it cannot write the local rattle.
        assert!(!tracker.apply_status(1, 2));
        assert_eq!(*world.ecs.get::<&ArrowShake>(arrow).unwrap(), ArrowShake(7));
        tracker.tick_interpolation(&mut world);
        assert_eq!(*world.ecs.get::<&ArrowShake>(arrow).unwrap(), ArrowShake(6));
        for _ in 0..6 {
            tracker.tick_interpolation(&mut world);
        }
        assert_eq!(*world.ecs.get::<&ArrowShake>(arrow).unwrap(), ArrowShake(0));
    }

    /// The arrow's block raycast is client-live, so a remotely spawned arrow advances between
    /// its sparse position packets rather than teleporting one second at a time.
    /// java: `EntityArrow.onUpdate` (`:237-245`, `:402-454`).
    #[test]
    fn arrow_air_tick_moves_then_applies_drag_and_gravity() {
        let mut world = World::new();
        let mut tracker = EntityTracker::new();
        let arrow = tracker.spawn(
            &mut world,
            60,
            TrackedKind::Type(EntityType::Arrow),
            None,
            [0, 64 * 32, 0],
            90.0,
            0.0,
            DVec3::new(1.0, 0.0, 0.0),
            Metadata::new(),
        );

        tracker.tick_interpolation(&mut world);

        assert_eq!(
            world.ecs.get::<&Position>(arrow).unwrap().0,
            DVec3::new(1.0, 64.0, 0.0)
        );
        let velocity = world.ecs.get::<&Velocity>(arrow).unwrap().0;
        assert_eq!(velocity.x.to_bits(), f64::from(0.99_f32).to_bits());
        assert_eq!(velocity.y.to_bits(), (-f64::from(0.05_f32)).to_bits());
        assert_eq!(*world.ecs.get::<&ArrowShake>(arrow).unwrap(), ArrowShake(0));
    }

    #[test]
    fn arrow_hit_enderman_teleports_before_the_arrow_false_damage_branch() {
        let mut world = World::new();
        for chunk_x in -2..=2 {
            for chunk_z in -2..=2 {
                world.load_empty_chunk(ChunkPos::new(chunk_x, chunk_z));
            }
        }
        let stone = BlockState::new(block_by_name("stone").expect("stone"), 0);
        for x in -32..=32 {
            for z in -32..=32 {
                world.set_block(BlockPos::new(x, 0, z), stone);
            }
        }

        let mut tracker = EntityTracker::new();
        let arrow = tracker.spawn(
            &mut world,
            60,
            TrackedKind::Type(EntityType::Arrow),
            None,
            [0, 64 * 32, 0],
            0.0,
            0.0,
            DVec3::new(2.0, 0.0, 0.0),
            Metadata::new(),
        );
        let enderman = tracker.spawn(
            &mut world,
            61,
            TrackedKind::Type(EntityType::Enderman),
            None,
            [3 * 16, 64 * 32, 0],
            0.0,
            0.0,
            DVec3::ZERO,
            Metadata::new(),
        );
        *tracker.particle_random_mut(61).unwrap() = JavaRandom::new(0xE11D_7777);
        let original_enderman_position = world.ecs.get::<&Position>(enderman).unwrap().0;

        tracker.tick_interpolation(&mut world);

        let events = tracker.take_particle_events();
        assert_eq!(
            events.len(),
            130,
            "128 teleport puffs plus two living plumes"
        );
        assert!(events[..128]
            .iter()
            .all(|event| event.particle_id == PORTAL));
        assert!(events[128..]
            .iter()
            .all(|event| event.particle_id == PORTAL));
        assert!(
            tracker.take_status_effect_events().is_empty(),
            "WorldClient's two Enderman portal sound calls have no RenderGlobal sound event"
        );
        assert_ne!(
            world.ecs.get::<&Position>(enderman).unwrap().0,
            original_enderman_position,
            "the client Enderman damage hook accepts a loaded destination"
        );
        let arrow_velocity = world.ecs.get::<&Velocity>(arrow).unwrap().0;
        assert!(
            arrow_velocity.x > 0.9,
            "a successful Enderman teleport leaves the arrow moving forward, got {arrow_velocity:?}"
        );
    }

    /// A critical arrow emits Java's four pre-movement `CRIT` particles, while an absent or
    /// wrong-typed index-16 watcher value is inert. This keeps the metadata trigger and the
    /// exact particle count under one present/absent/wrong-type control.
    #[test]
    fn arrow_critical_watcher_emits_four_particles_and_rejects_bad_types() {
        let mut world = World::new();
        let mut tracker = EntityTracker::new();
        let mut critical_metadata = Metadata::new();
        critical_metadata.set(16, mc_world::entity::MetadataValue::Byte(1));
        tracker.spawn(
            &mut world,
            60,
            TrackedKind::Type(EntityType::Arrow),
            None,
            [0, 64 * 32, 0],
            90.0,
            0.0,
            DVec3::new(1.0, 0.0, 0.0),
            critical_metadata,
        );
        tracker.spawn(
            &mut world,
            61,
            TrackedKind::Type(EntityType::Arrow),
            None,
            [10 * 32, 64 * 32, 0],
            90.0,
            0.0,
            DVec3::new(1.0, 0.0, 0.0),
            Metadata::new(),
        );
        let mut wrong_type_metadata = Metadata::new();
        wrong_type_metadata.set(16, mc_world::entity::MetadataValue::Str("critical".into()));
        tracker.spawn(
            &mut world,
            62,
            TrackedKind::Type(EntityType::Arrow),
            None,
            [20 * 32, 64 * 32, 0],
            90.0,
            0.0,
            DVec3::new(1.0, 0.0, 0.0),
            wrong_type_metadata,
        );

        tracker.tick_interpolation(&mut world);

        let events = tracker.take_particle_events();
        assert_eq!(
            events.len(),
            4,
            "only the present, correctly typed bit emits CRIT"
        );
        for (step, event) in events.iter().enumerate() {
            assert_eq!(event.particle_id, CRIT);
            assert_eq!(event.position.x, step as f64 * 0.25);
            assert_eq!(event.position.y, 64.0);
            assert_eq!(event.position.z, 0.0);
            assert_eq!(event.velocity, DVec3::new(-1.0, 0.2, 0.0));
            assert!(event.args.is_empty());
        }
    }

    /// `EntityArrow`'s water branch runs after it has moved by its old motion: four bubbles at
    /// `pos - motion * 0.25` and 0.6F instead of the ordinary 0.99F drag. The branch reads
    /// `isInWater()`, the latch set from the *pre-move* box (`javap -c wq.t_()` offset 1973 ->
    /// `pk.V()`), so an arrow leaving a water cell still takes the water tick and one entering a
    /// water cell does not yet. This test used to move the arrow *into* water and expect the
    /// water tick at once, which was the post-move probe bug.
    /// java: `EntityArrow.onUpdate` (`:432-454`), `Entity.isInWater` (`:1103-1106`).
    #[test]
    fn arrow_water_tick_emits_four_bubbles_and_uses_water_drag() {
        let mut world = resident_test_world();
        let water = BlockState::new(block_by_name("water").unwrap(), 0);
        world.set_block(BlockPos::new(0, 64, 0), water);
        world.set_block(BlockPos::new(11, 64, 0), water);
        let mut tracker = EntityTracker::new();
        let arrow = tracker.spawn(
            &mut world,
            60,
            TrackedKind::Type(EntityType::Arrow),
            None,
            [16, 64 * 32, 16],
            90.0,
            0.0,
            DVec3::new(1.0, 0.0, 0.0),
            Metadata::new(),
        );
        let entering_arrow = tracker.spawn(
            &mut world,
            61,
            TrackedKind::Type(EntityType::Arrow),
            None,
            [10 * 32 + 16, 64 * 32, 16],
            90.0,
            0.0,
            DVec3::new(1.0, 0.0, 0.0),
            Metadata::new(),
        );

        tracker.tick_interpolation(&mut world);

        assert_eq!(
            world.ecs.get::<&Position>(arrow).unwrap().0,
            DVec3::new(1.5, 64.0, 0.5)
        );
        let velocity = world.ecs.get::<&Velocity>(arrow).unwrap().0;
        assert_eq!(velocity.x.to_bits(), f64::from(0.6_f32).to_bits());
        assert_eq!(velocity.y.to_bits(), (-f64::from(0.05_f32)).to_bits());
        let entering_velocity = world.ecs.get::<&Velocity>(entering_arrow).unwrap().0;
        assert_eq!(
            entering_velocity.x.to_bits(),
            f64::from(0.99_f32).to_bits(),
            "an arrow that has only just moved into water keeps the air drag this tick"
        );

        let bubbles = tracker.take_particle_events();
        assert_eq!(bubbles.len(), 4, "only the arrow that started wet bubbles");
        for bubble in bubbles {
            assert_eq!(bubble.particle_id, WATER_BUBBLE);
            assert_eq!(bubble.position, DVec3::new(1.25, 64.0, 0.5));
            assert_eq!(bubble.velocity, DVec3::new(1.0, 0.0, 0.0));
            assert!(bubble.args.is_empty());
        }
    }

    /// A block hit starts `arrowShake` after its start-of-tick decrement, backs the arrow off
    /// the face by 0.05F, and leaves it embedded on later ticks instead of re-hitting forever.
    /// java: `EntityArrow.onUpdate` (`:204-207`, `:237-245`, `:370-405`).
    #[test]
    fn arrow_block_impact_produces_shake_and_stays_embedded() {
        let mut world = resident_test_world();
        world.set_block(
            BlockPos::new(1, 64, 0),
            BlockState::new(block_by_name("stone").unwrap(), 0),
        );
        let mut tracker = EntityTracker::new();
        let mut metadata = Metadata::new();
        metadata.set(16, mc_world::entity::MetadataValue::Byte(1));
        let arrow = tracker.spawn(
            &mut world,
            60,
            TrackedKind::Type(EntityType::Arrow),
            None,
            [16, 64 * 32, 16],
            90.0,
            0.0,
            DVec3::new(1.0, 0.0, 0.0),
            metadata,
        );

        tracker.tick_interpolation(&mut world);

        assert_eq!(
            world.ecs.get::<&Position>(arrow).unwrap().0,
            DVec3::new(1.0 - 0.050_000_000_745_058_06, 64.0, 0.5),
            "the hit is backed off by EntityArrow's 0.05000000074505806D"
        );
        assert_eq!(*world.ecs.get::<&ArrowShake>(arrow).unwrap(), ArrowShake(7));
        let after_hit = world.ecs.get::<&Velocity>(arrow).unwrap().0;
        assert_eq!(
            after_hit.x.to_bits(),
            f64::from(0.5_f32 * 0.99_f32).to_bits()
        );
        assert_eq!(
            after_hit.y.to_bits(),
            (-f64::from(0.05_f32)).to_bits(),
            "the collision tail still applies arrow gravity once"
        );
        assert!(
            tracker.take_particle_events().is_empty(),
            "block impact clears critical before the four-particle tail"
        );
        assert_eq!(
            world.ecs.get::<&Metadata>(arrow).unwrap().get(16),
            Some(&mc_world::entity::MetadataValue::Byte(0))
        );

        tracker.tick_interpolation(&mut world);
        assert_eq!(
            world.ecs.get::<&Position>(arrow).unwrap().0,
            DVec3::new(1.0 - 0.050_000_000_745_058_06, 64.0, 0.5),
            "the stored inTile/inData equivalent prevents a second local impact"
        );
        assert_eq!(*world.ecs.get::<&ArrowShake>(arrow).unwrap(), ArrowShake(6));
        assert_eq!(world.ecs.get::<&Velocity>(arrow).unwrap().0, after_hit);
    }

    /// An entity intercept takes precedence over the later block trace, but because
    /// `attackEntityFrom` is false on a client it reaches only EntityArrow's small reverse
    /// bounce.  In particular it must not borrow the block's embedding/shake state.
    /// java: `EntityArrow.onUpdate` (`:245-337`).
    #[test]
    fn arrow_entity_intercept_bounces_without_embedding_or_damage_prediction() {
        let mut world = World::new();
        world.set_block(
            BlockPos::new(1, 64, 0),
            BlockState::new(block_by_name("stone").unwrap(), 0),
        );
        let mut tracker = EntityTracker::new();
        let arrow = tracker.spawn(
            &mut world,
            60,
            TrackedKind::Type(EntityType::Arrow),
            None,
            [0, 64 * 32, 0],
            90.0,
            0.0,
            DVec3::new(1.0, 0.0, 0.0),
            Metadata::new(),
        );
        tracker.spawn(
            &mut world,
            61,
            TrackedKind::Type(EntityType::Zombie),
            None,
            [32, 64 * 32, 0],
            0.0,
            0.0,
            DVec3::ZERO,
            Metadata::new(),
        );

        tracker.tick_interpolation(&mut world);

        assert_eq!(
            world.ecs.get::<&Position>(arrow).unwrap().0,
            DVec3::new(-f64::from(0.1_f32), 64.0, 0.0),
            "the client-only false-damage branch moves by the reversed 0.1F motion"
        );
        let velocity = world.ecs.get::<&Velocity>(arrow).unwrap().0;
        assert_eq!(
            velocity.x.to_bits(),
            (-f64::from(0.1_f32) * f64::from(0.99_f32)).to_bits()
        );
        assert_eq!(velocity.y.to_bits(), (-f64::from(0.05_f32)).to_bits());
        assert_eq!(*world.ecs.get::<&ArrowShake>(arrow).unwrap(), ArrowShake(0));
        assert_eq!(
            world.ecs.get::<&ArrowFlight>(arrow).unwrap().embedded,
            None,
            "the nearer entity suppresses the block impact rather than embedding the arrow"
        );
        // java: the bounce adds 180 to `prevRotationYaw` too, so the rendered arrow flips at
        // once instead of spinning through half a turn across the tick.
        let tracked = tracker.get(60).expect("a bounced arrow stays");
        assert_eq!(tracked.render.prev_body_yaw, 270.0);
        let (yaw, _) = current_rotation(&world, tracked);
        let turn = (yaw - tracked.render.prev_body_yaw).rem_euclid(360.0);
        assert!(
            turn.min(360.0 - turn) < 1e-3,
            "reversed motion leaves the eased yaw on the flipped sample: {yaw}"
        );
    }

    /// java: `EntityOtherPlayerMP.attackEntityFrom` is a bare `return true`, so a client arrow
    /// that reaches a remote player takes the hit branch, `setDead()`, and `World.updateEntities`
    /// removes it in the same tick: it vanishes on contact rather than bouncing back off the
    /// player (a client mob, above, returns false and does bounce). A boat is the non-living
    /// `true` case.
    #[test]
    fn arrow_hitting_a_remote_player_or_a_boat_vanishes_instead_of_bouncing() {
        // The boat is 1.5 wide: two blocks out keeps the arrow's start outside its inflated box.
        for (kind, uuid, x) in [
            (TrackedKind::Player, Some(Uuid::from_u128(61)), 32),
            (TrackedKind::Type(EntityType::Boat), None, 64),
            (TrackedKind::Type(EntityType::Zombie), None, 32),
        ] {
            let mut world = World::new();
            world.set_block(
                BlockPos::new(10, 60, 10),
                BlockState::new(block_by_name("stone").unwrap(), 0),
            );
            let mut tracker = EntityTracker::new();
            tracker.spawn(
                &mut world,
                60,
                TrackedKind::Type(EntityType::Arrow),
                None,
                [0, 64 * 32, 0],
                90.0,
                0.0,
                DVec3::new(1.0, 0.0, 0.0),
                Metadata::new(),
            );
            tracker.spawn(
                &mut world,
                61,
                kind,
                uuid,
                [x, 64 * 32, 0],
                0.0,
                0.0,
                DVec3::ZERO,
                Metadata::new(),
            );

            tracker.tick_interpolation(&mut world);

            assert!(tracker.get(61).is_some(), "{kind:?}: the target stays");
            let bounces = kind == TrackedKind::Type(EntityType::Zombie);
            assert_eq!(
                tracker.get(60).is_some(),
                bounces,
                "{kind:?}: a client `attackEntityFrom` of true removes the arrow on contact"
            );
        }
        assert!(arrow_hit_accepted_on_client(TrackedKind::Type(
            EntityType::EnderCrystal
        )));
        assert!(!arrow_hit_accepted_on_client(TrackedKind::Type(
            EntityType::PrimedTnt
        )));
        assert!(!arrow_hit_accepted_on_client(TrackedKind::Type(
            EntityType::ArmorStand
        )));
    }

    /// java: the local `EntityPlayerSP` is in the client world's
    /// entity lists, so `EntityArrow`'s sweep can pick it; its `attackEntityFrom` returns false,
    /// so the arrow takes the reverse-0.1 bounce (ending at x = -0.1 here). It passes through when
    /// `capabilities.disableDamage` is set (creative) or when a teammate with friendly fire off
    /// shot it. Negative control: without the local player in the sweep (the old code, the last
    /// case) the arrow flew straight through the player.
    #[test]
    fn an_arrow_bounces_off_the_local_player_unless_it_may_not_hit_them() {
        use crate::sync::event::ScoreboardEvent;
        use crate::sync::scoreboard::Scoreboard;
        use mc_protocol::play::s2c::{TeamInfo, Teams, TeamsAction};

        const LOCAL_ID: i32 = 5;
        let board_with = |friendly_flags: Option<i8>| {
            let mut board = Scoreboard::new();
            if let Some(friendly_flags) = friendly_flags {
                board.apply(&ScoreboardEvent::Teams(Box::new(Teams {
                    team_name: "red".into(),
                    action: TeamsAction::Create {
                        info: TeamInfo {
                            display_name: "red".into(),
                            prefix: String::new(),
                            suffix: String::new(),
                            friendly_flags,
                            name_tag_visibility: "always".into(),
                            color: -1,
                        },
                        players: vec!["Archer".into(), "Me".into()],
                    },
                })));
            }
            board
        };
        // The local player stands one block ahead of the arrow: feet at x = 1, width 0.6.
        let local_box = Aabb::new(DVec3::new(0.7, 64.0, -0.3), DVec3::new(1.3, 65.8, 0.3));
        // (team friendly flags, disableDamage, local player in the sweep, bounces)
        let cases = [
            (None, false, true, true),
            (Some(1), false, true, true),
            (None, true, true, false),
            (Some(0), false, true, false),
            (None, false, false, false),
        ];
        for (flags, disable_damage, in_sweep, bounces) in cases {
            let board = board_with(flags);
            let mut world = World::new();
            let mut tracker = EntityTracker::new();
            let arrow = tracker.spawn(
                &mut world,
                60,
                TrackedKind::Type(EntityType::Arrow),
                None,
                [0, 64 * 32, 0],
                90.0,
                0.0,
                DVec3::new(1.0, 0.0, 0.0),
                Metadata::new(),
            );
            tracker.spawn(
                &mut world,
                70,
                TrackedKind::Player,
                Some(Uuid::from_u128(70)),
                [-320, 64 * 32, 0],
                0.0,
                0.0,
                DVec3::ZERO,
                Metadata::new(),
            );
            tracker.by_network_id.get_mut(&70).unwrap().player_profile =
                Some(PlayerProfileSnapshot {
                    username: "Archer".to_owned(),
                    properties: Vec::new(),
                    trusted_textures: crate::sync::players::TrustedTextures::default(),
                });
            world
                .ecs
                .insert_one(arrow, mc_world::ArrowShooter(70))
                .unwrap();
            let view = ArrowTeamView {
                scoreboard: &board,
                local_entity_id: LOCAL_ID,
                local_username: "Me",
                local_box: in_sweep.then_some(local_box),
                local_disable_damage: disable_damage,
            };
            tracker
                .tick_interpolation_with_local_player_in_dimension_and_weather_with_riders_and_teams(
                    &mut world,
                    None,
                    &PlayerList::new(),
                    0,
                    false,
                    None,
                    None,
                    Some(view),
                );

            let label =
                format!("flags {flags:?}, disableDamage {disable_damage}, in sweep {in_sweep}");
            assert!(
                tracker.get(60).is_some(),
                "{label}: a client arrow never dies on the local player"
            );
            let x = world.ecs.get::<&Position>(arrow).unwrap().0.x;
            let expected = if bounces { -f64::from(0.1_f32) } else { 1.0 };
            assert_eq!(x, expected, "{label}");
        }
    }

    /// java: `EntityArrow.onUpdate:278-285`. When the nearest hit
    /// is a player and `shootingEntity` is a player that `canAttackPlayer` refuses (both in one
    /// scoreboard team whose friendly-fire bit is clear), `movingobjectposition = null`: the
    /// client arrow neither vanishes on the teammate nor embeds, it moves on by its whole motion.
    /// The shooter may be a remote player or the local player. Controls: friendly fire on (bit
    /// 0 set), and no scoreboard at all, both keep the old hit (the arrow vanishes on contact).
    /// Negative control: before this, every case below vanished.
    #[test]
    fn a_teammates_arrow_flies_through_when_friendly_fire_is_off() {
        use crate::sync::event::ScoreboardEvent;
        use crate::sync::scoreboard::Scoreboard;
        use mc_protocol::play::s2c::{TeamInfo, Teams, TeamsAction};

        const LOCAL_ID: i32 = 5;
        let team = |friendly_flags: i8| {
            let mut board = Scoreboard::new();
            board.apply(&ScoreboardEvent::Teams(Box::new(Teams {
                team_name: "red".into(),
                action: TeamsAction::Create {
                    info: TeamInfo {
                        display_name: "red".into(),
                        prefix: String::new(),
                        suffix: String::new(),
                        friendly_flags,
                        name_tag_visibility: "always".into(),
                        color: -1,
                    },
                    players: vec!["Archer".into(), "Target".into()],
                },
            })));
            board
        };
        let profile = |name: &str| PlayerProfileSnapshot {
            username: name.to_owned(),
            properties: Vec::new(),
            trusted_textures: crate::sync::players::TrustedTextures::default(),
        };
        // (scoreboard, the local player shot it, the arrow flies through)
        let cases = [
            (Some(team(0)), false, true),
            (Some(team(0)), true, true),
            (Some(team(2)), false, true),
            (Some(team(1)), false, false),
            (Some(team(3)), true, false),
            (None, false, false),
        ];
        for (board, local_shooter, passes) in cases {
            let mut world = World::new();
            let mut tracker = EntityTracker::new();
            let arrow = tracker.spawn(
                &mut world,
                60,
                TrackedKind::Type(EntityType::Arrow),
                None,
                [0, 64 * 32, 0],
                90.0,
                0.0,
                DVec3::new(1.0, 0.0, 0.0),
                Metadata::new(),
            );
            tracker.spawn(
                &mut world,
                61,
                TrackedKind::Player,
                Some(Uuid::from_u128(61)),
                [32, 64 * 32, 0],
                0.0,
                0.0,
                DVec3::ZERO,
                Metadata::new(),
            );
            tracker.by_network_id.get_mut(&61).unwrap().player_profile = Some(profile("Target"));
            let shooter = if local_shooter {
                LOCAL_ID
            } else {
                // Ten blocks behind the arrow, out of its sweep.
                tracker.spawn(
                    &mut world,
                    70,
                    TrackedKind::Player,
                    Some(Uuid::from_u128(70)),
                    [-320, 64 * 32, 0],
                    0.0,
                    0.0,
                    DVec3::ZERO,
                    Metadata::new(),
                );
                tracker.by_network_id.get_mut(&70).unwrap().player_profile =
                    Some(profile("Archer"));
                70
            };
            world
                .ecs
                .insert_one(arrow, mc_world::ArrowShooter(shooter))
                .unwrap();

            let teams = board.as_ref().map(|scoreboard| ArrowTeamView {
                scoreboard,
                local_entity_id: LOCAL_ID,
                local_username: "Archer",
                local_box: None,
                local_disable_damage: false,
            });
            tracker
                .tick_interpolation_with_local_player_in_dimension_and_weather_with_riders_and_teams(
                    &mut world,
                    None,
                    &PlayerList::new(),
                    0,
                    false,
                    None,
                    None,
                    teams,
                );

            let label = format!(
                "flags {:?}, local shooter {local_shooter}",
                board
                    .as_ref()
                    .and_then(|b| b.player_team("Archer").map(|t| t.friendly_flags))
            );
            assert_eq!(tracker.get(60).is_some(), passes, "{label}");
            if passes {
                assert_eq!(
                    world.ecs.get::<&Position>(arrow).unwrap().0,
                    DVec3::new(1.0, 64.0, 0.0),
                    "{label}: the whole motion, no hit and no embedding"
                );
                assert_eq!(
                    world.ecs.get::<&ArrowFlight>(arrow).unwrap().embedded,
                    None,
                    "{label}"
                );
            }
        }
    }

    /// The shooter is the one exception to a normal collidable entity, and only through air
    /// tick four.  This is a separate direct sweep probe so the test cannot pass merely because
    /// a short arrow segment failed to reach its owner.
    /// java: `EntityArrow.onUpdate` (`:254`).
    #[test]
    fn arrow_owner_becomes_a_sweep_candidate_on_the_fifth_air_tick() {
        let mut world = World::new();
        let mut tracker = EntityTracker::new();
        let arrow = tracker.spawn(
            &mut world,
            70,
            TrackedKind::Type(EntityType::Arrow),
            None,
            [0, 64 * 32, 0],
            0.0,
            0.0,
            DVec3::ZERO,
            Metadata::new(),
        );
        let shooter = tracker.spawn(
            &mut world,
            71,
            TrackedKind::Type(EntityType::Zombie),
            None,
            [32, 64 * 32, 0],
            0.0,
            0.0,
            DVec3::ZERO,
            Metadata::new(),
        );
        world
            .ecs
            .insert_one(arrow, mc_world::ArrowShooter(71))
            .unwrap();
        let candidate = ArrowCollisionCandidate {
            network_id: 71,
            entity: shooter,
            kind: TrackedKind::Type(EntityType::Zombie),
            dead: false,
            marker: false,
            width: tracker.get(71).unwrap().dimensions().0,
            height: tracker.get(71).unwrap().dimensions().1,
        };
        let start = DVec3::new(0.0, 64.0, 0.0);
        let end = DVec3::new(2.0, 64.0, 0.0);

        assert_eq!(
            arrow_entity_hit(&world, arrow, start, end, 4, &[candidate], None),
            None
        );
        assert_eq!(
            arrow_entity_hit(&world, arrow, start, end, 5, &[candidate], None),
            Some(71)
        );
    }

