    /// `EntityFireball.onUpdate` emits four water bubbles (when submerged) before one smoke
    /// puff. These are client-local effects rather than S2A packets, so the tracker exposes the
    /// exact particle-spawn inputs to the app particle seam.
    #[test]
    fn a_submerged_fireball_queues_four_bubbles_then_one_smoke_puff() {
        let mut world = World::new();
        let water = mc_data::BlockState::new(mc_data::block_by_name("water").unwrap(), 0);
        mc_physics::scene::fill(
            &mut world,
            mc_math::BlockPos::new(-1, 0, -2),
            mc_math::BlockPos::new(1, 1, 1),
            water,
        );
        let mut tracker = EntityTracker::new();
        let entity = tracker.spawn(
            &mut world,
            12,
            fireball(),
            None,
            [0, 0, 0],
            0.0,
            0.0,
            DVec3::new(0.25, 0.0, -0.5),
            Metadata::new(),
        );
        world
            .ecs
            .insert_one(entity, mc_world::Acceleration(DVec3::ZERO))
            .unwrap();

        tracker.tick_interpolation(&mut world);
        let events = tracker.take_particle_events();
        assert_eq!(events.len(), 5);
        let bubble_position = DVec3::new(0.1875, 0.0, -0.375);
        for bubble in &events[..4] {
            assert_eq!(bubble.particle_id, WATER_BUBBLE);
            assert_eq!(bubble.position, bubble_position);
            assert_eq!(bubble.velocity, DVec3::new(0.25, 0.0, -0.5));
            assert!(bubble.args.is_empty());
        }
        assert_eq!(events[4].particle_id, SMOKE_NORMAL);
        assert_eq!(events[4].position, DVec3::new(0.25, 0.5, -0.5));
        assert_eq!(events[4].velocity, DVec3::ZERO);
        assert!(events[4].args.is_empty());
        assert!(
            tracker.take_particle_events().is_empty(),
            "drain is one-shot"
        );
    }

