    /// java: spawn-object type 77 carries the fence block corner, then the client floors it to
    /// a `BlockPos` and `EntityLeashKnot` adds half a block on all three axes. The deliberately
    /// fractional fixed-point sample is the negative control for replacing `floor + 0.5` with
    /// a naive raw-coordinate `+ 0.5`.
    /// A leash S1B that arrives before its holder resolves at the holder's spawn; the spawn-time
    /// resolution walk is gated on the only two writers that can leave a leash unresolved.
    #[test]
    fn leash_before_holder_resolves_at_spawn_and_gates_the_resolution_walk() {
        use mc_protocol::play::s2c::{AttachType, EntityAttach};

        let mut world = World::new();
        let mut tracker = EntityTracker::new();
        let leash = |entity_id, vehicle_entity_id| EntityAttach {
            entity_id,
            vehicle_entity_id,
            attach_type: AttachType::Leash,
        };
        tracker.spawn(
            &mut world,
            10,
            TrackedKind::Type(EntityType::Cow),
            None,
            [0, 64 * 32, 0],
            0.0,
            0.0,
            DVec3::ZERO,
            Metadata::new(),
        );
        spawn_at(&mut tracker, &mut world, 11, [32, 64 * 32, 0]);
        assert!(!tracker.pending_leash_possible);
        // A resolved holder never needs the spawn walk.
        assert!(tracker.apply_entity_attach(&mut world, &leash(11, 10)));
        assert!(!tracker.pending_leash_possible);

        // The holder has not spawned yet: the raw id is kept and the gate opens.
        assert!(tracker.apply_entity_attach(&mut world, &leash(10, 12)));
        assert!(tracker.pending_leash_possible);
        assert_eq!(tracker.get(10).unwrap().leashed_to(), Some(12));
        assert_eq!(tracker.get(10).unwrap().leash_holder_entity(), None);
        let holder = tracker.spawn(
            &mut world,
            12,
            zombie(),
            None,
            [64, 64 * 32, 0],
            0.0,
            0.0,
            DVec3::ZERO,
            Metadata::new(),
        );
        assert_eq!(tracker.get(10).unwrap().leash_holder_entity(), Some(holder));
        assert_eq!(tracker.get(11).unwrap().leashed_to(), Some(10));

        tracker.clear();
        assert!(!tracker.pending_leash_possible);
    }

    #[test]
    fn a_leash_knot_spawns_at_the_center_of_its_fence_block() {
        let mut world = World::new();
        let mut tracker = EntityTracker::new();
        tracker.spawn(
            &mut world,
            77,
            TrackedKind::Type(EntityType::LeashKnot),
            None,
            [32 * 3 + 31, 32 * 2 + 1, -32 * 4 + 1],
            0.0,
            0.0,
            DVec3::ZERO,
            Metadata::new(),
        );

        let tracked = tracker.get(77).unwrap();
        let position = world.ecs.get::<&Position>(tracked.entity).unwrap().0;
        assert_eq!(position, DVec3::new(3.5, 2.5, -3.5));
        assert_eq!(tracked.target_pos, position);
        assert_eq!(
            tracked.server_pos,
            [32 * 3 + 31, 32 * 2 + 1, -32 * 4 + 1],
            "the wire fixed-point baseline remains untouched"
        );
    }

    /// java: S14 -> S01 §13 cross-section request, closed. A remote player used to be spawned
    /// with no `EntityKind` component at all — `RemotePlayer` stood in for it — so a caller
    /// after "every drawable entity" had to run a second, disjoint query just for players. It
    /// now gets `EntityKind::Player` like every mob and object, plus `RemotePlayer` for the
    /// uuid/network-id data `EntityKind` has nowhere to put.
    #[test]
    fn a_spawned_player_resolves_through_the_same_entity_kind_component_as_a_mob() {
        let mut world = World::new();
        let mut tracker = EntityTracker::new();
        let uuid = Uuid::from_u128(0xC0FFEE);
        let entity = tracker.spawn(
            &mut world,
            9,
            TrackedKind::Player,
            Some(uuid),
            [0, 0, 0],
            0.0,
            0.0,
            DVec3::ZERO,
            Metadata::new(),
        );

        let kind = world
            .ecs
            .get::<&EntityKind>(entity)
            .expect("every tracked entity now carries an EntityKind, players included");
        assert_eq!(*kind, EntityKind::Player);
        drop(kind);

        let marker = world
            .ecs
            .get::<&RemotePlayer>(entity)
            .expect("RemotePlayer still carries the uuid/network-id EntityKind cannot");
        assert_eq!(marker.uuid, uuid);
        assert_eq!(marker.network_id, 9);
    }

    /// java: `WorldClient.addEntityToWorld` removes an entity already holding the id.
    #[test]
    fn respawning_the_same_id_replaces_the_old_entity() {
        let mut world = World::new();
        let mut tracker = EntityTracker::new();
        spawn_at(&mut tracker, &mut world, 7, [0, 0, 0]);
        let first = tracker.get(7).unwrap().entity;
        spawn_at(&mut tracker, &mut world, 7, [32, 32, 32]);
        let second = tracker.get(7).unwrap().entity;
        assert_ne!(first, second);
        assert!(
            world.ecs.get::<&Position>(first).is_err(),
            "old one is gone"
        );
        assert_eq!(tracker.len(), 1);
    }

    #[test]
    fn dropped_item_hover_phase_is_spawn_owned_across_id_reuse() {
        let mut world = World::new();
        let mut tracker = EntityTracker::new();
        let spawn_item = |tracker: &mut EntityTracker, world: &mut World, id| {
            tracker.spawn(
                world,
                id,
                TrackedKind::Type(EntityType::Item),
                None,
                [0, 64 * 32, 0],
                0.0,
                0.0,
                DVec3::ZERO,
                Metadata::new(),
            );
            tracker.get(id).unwrap().dropped_item_hover_start
        };

        let first = spawn_item(&mut tracker, &mut world, 7);
        assert_eq!(tracker.get(7).unwrap().dropped_item_hover_start, first);
        let distinct = spawn_item(&mut tracker, &mut world, 8);
        let reused = spawn_item(&mut tracker, &mut world, 7);

        assert!((0.0..core::f32::consts::TAU).contains(&first));
        assert!((0.0..core::f32::consts::TAU).contains(&distinct));
        assert!((0.0..core::f32::consts::TAU).contains(&reused));
        assert_ne!(
            first, distinct,
            "simultaneous items need independent phases"
        );
        assert_ne!(
            first, reused,
            "reusing a network id constructs a fresh phase"
        );
    }

    #[test]
    fn ender_crystal_phase_is_spawn_owned_and_reaches_render_params() {
        let mut world = World::new();
        let mut tracker = EntityTracker::new();
        let spawn_crystal = |tracker: &mut EntityTracker, world: &mut World, id| {
            tracker.spawn(
                world,
                id,
                TrackedKind::Type(EntityType::EnderCrystal),
                None,
                [0, 64 * 32, 0],
                0.0,
                0.0,
                DVec3::ZERO,
                Metadata::new(),
            );
            let tracked = tracker.get(id).unwrap();
            assert_eq!(
                tracked.render_params(0.5).entity.crystal_inner_rotation,
                tracked.crystal_inner_rotation
            );
            tracked.crystal_inner_rotation
        };

        let first = spawn_crystal(&mut tracker, &mut world, 7);
        let distinct = spawn_crystal(&mut tracker, &mut world, 8);
        let reused = spawn_crystal(&mut tracker, &mut world, 7);
        for phase in [first, distinct, reused] {
            assert!((0.0..100_000.0).contains(&phase));
        }
        assert_ne!(
            first, distinct,
            "same-tick crystals need independent phases"
        );
        assert_ne!(first, reused, "id reuse must construct a fresh phase");
    }

