    /// java: `EntityLivingBase.onUpdate` runs `onDeathUpdate` (`:400`, `++deathTime`) once
    /// health hits zero, by either route the server has — the watched value or status opcode 3.
    #[test]
    fn death_time_advances_from_either_death_signal() {
        use mc_protocol::{MetadataEntry, MetadataValue as Wire};
        let mut world = World::new();
        let mut tracker = EntityTracker::new();
        spawn_at(&mut tracker, &mut world, 1, [0, 0, 0]);
        spawn_at(&mut tracker, &mut world, 2, [0, 0, 0]);

        // 1: the status opcode. 2: the watched health value.
        assert!(tracker.apply_status(1, 3));
        assert!(tracker.apply_metadata(
            &mut world,
            2,
            &vec![MetadataEntry {
                index: 6,
                value: Wire::Float(0.0),
            }],
        ));
        for _ in 0..4 {
            tracker.tick_interpolation(&mut world);
        }
        assert_eq!(tracker.get(1).unwrap().render.death_time, 4);
        assert_eq!(tracker.get(2).unwrap().render.death_time, 4);

        // Healing resets it — a mob that was at zero and is not any more is not a corpse.
        assert!(tracker.apply_metadata(
            &mut world,
            2,
            &vec![MetadataEntry {
                index: 6,
                value: Wire::Float(20.0),
            }],
        ));
        tracker.tick_interpolation(&mut world);
        assert_eq!(tracker.get(2).unwrap().render.death_time, 0);

        // java: `onDeathUpdate` (`:402-424`) — `if (this.deathTime == 20) { … this.setDead(); … }`,
        // and `setDead()` is **outside** the `!worldObj.isRemote` guard, so the client removes
        // the corpse itself one second after the death animation starts. This block used to
        // assert the counter clamped at 20 and the body stayed put, which is what mc-rs did and
        // vanilla does not: the corpse lingered until `S13PacketDestroyEntities` arrived.
        // Five ticks have run, so `death_time` is 5; fourteen more take it to 19.
        let entity = tracker.get(1).unwrap().entity;
        for _ in 0..(MAX_DEATH_TIME - 6) {
            tracker.tick_interpolation(&mut world);
        }
        assert_eq!(
            tracker.get(1).unwrap().render.death_time,
            MAX_DEATH_TIME - 1,
            "one tick short of setDead()"
        );
        tracker.tick_interpolation(&mut world);
        assert!(
            tracker.get(1).is_none(),
            "setDead() at deathTime == 20, without waiting for DestroyEntities"
        );
        assert!(
            world.ecs.get::<&Position>(entity).is_err(),
            "and the ECS entity goes with it"
        );
        // The healed one is untouched.
        assert!(tracker.get(2).is_some());
    }

    /// java: `EntityLivingBase.onDeathUpdate` queues twenty `EXPLOSION_NORMAL` puffs exactly on
    /// the `deathTime == 20` edge, after the nineteen retained corpse ticks. This pins the
    /// Gaussian/spread order and proves there is no duplicate burst on a clamped/dead generation.
    #[test]
    fn living_death_edge_emits_one_exact_explosion_burst() {
        let mut world = World::new();
        let mut tracker = EntityTracker::new();
        spawn_at(&mut tracker, &mut world, 1, [0, 64 * 32, 0]);
        assert!(tracker.apply_status(1, 3));
        let seed = 0xDEA7_i64;
        *tracker.particle_random_mut(1).unwrap() = JavaRandom::new(seed);
        let width = EntityType::Zombie.info().width;
        let height = EntityType::Zombie.info().height;
        let mut oracle = JavaRandom::new(seed);
        for _ in 0..19 {
            tracker.tick_interpolation(&mut world);
            assert!(tracker.take_particle_events().is_empty());
        }
        assert_eq!(
            tracker.get(1).unwrap().render.death_time,
            MAX_DEATH_TIME - 1
        );

        let dx = oracle.next_gaussian() * 0.02;
        let dy = oracle.next_gaussian() * 0.02;
        let dz = oracle.next_gaussian() * 0.02;
        let x = oracle.next_f32() * width * 2.0 - width;
        let y = oracle.next_f32() * height;
        let z = oracle.next_f32() * width * 2.0 - width;
        tracker.tick_interpolation(&mut world);
        assert!(
            tracker.get(1).is_none(),
            "deathTime 20 removes the client corpse"
        );
        let events = tracker.take_particle_events();
        assert_eq!(events.len(), 20);
        assert!(events
            .iter()
            .all(|event| { event.particle_id == EXPLOSION_NORMAL && event.args.is_empty() }));
        assert_eq!(
            events[0],
            EntityParticleEvent {
                particle_id: EXPLOSION_NORMAL,
                position: DVec3::new(x as f64, 64.0 + y as f64, z as f64),
                velocity: DVec3::new(dx, dy, dz),
                args: EntityParticleArgs::EMPTY,
            }
        );
        assert!(tracker.take_particle_events().is_empty());
    }

    /// F-P1-entity.player-01-13: only EntityPlayer overrides onDeath with the narrow box and
    /// yaw kick. A later velocity must survive ordinary corpse ticks, and healing must clear the
    /// one-shot latch so a later death can apply again without leaking dimensions across lives.
    #[test]
    fn remote_player_death_pose_is_player_only_one_shot_and_resets_on_heal() {
        use mc_protocol::{MetadataEntry, MetadataValue as Wire};

        let mut world = World::new();
        let mut tracker = EntityTracker::new();
        let player = tracker.spawn(
            &mut world,
            1,
            TrackedKind::Player,
            Some(Uuid::from_u128(1)),
            [0, 64 * 32, 0],
            90.0,
            0.0,
            DVec3::new(0.4, -0.2, 0.3),
            Metadata::new(),
        );
        let zombie = tracker.spawn(
            &mut world,
            2,
            TrackedKind::Type(EntityType::Zombie),
            None,
            [2 * 32, 64 * 32, 0],
            90.0,
            0.0,
            DVec3::new(0.4, -0.2, 0.3),
            Metadata::new(),
        );

        assert!(tracker.apply_status_in_world(&world, 1, 3));
        assert!(tracker.apply_status_in_world(&world, 2, 3));
        let angle = 90.0_f32 * core::f32::consts::PI / 180.0;
        let expected = DVec3::new(
            f64::from(-math_helper::cos(angle) * 0.1),
            0.10000000149011612,
            f64::from(-math_helper::sin(angle) * 0.1),
        );
        assert_eq!(
            world.ecs.get::<&Velocity>(player).unwrap().0,
            expected,
            "status 3 applies the exact float-LUT player kick"
        );
        assert_eq!(
            (
                tracker.get(1).unwrap().width,
                tracker.get(1).unwrap().height
            ),
            (0.2, 0.2)
        );
        assert_eq!(
            world.ecs.get::<&Velocity>(zombie).unwrap().0,
            DVec3::new(0.4, -0.2, 0.3),
            "ordinary living death does not inherit EntityPlayer.onDeath"
        );
        assert_ne!(
            (
                tracker.get(2).unwrap().width,
                tracker.get(2).unwrap().height
            ),
            (0.2, 0.2)
        );

        // A later packet owns velocity; the continuing death timer must not replay the kick.
        world.ecs.get::<&mut Velocity>(player).unwrap().0 = DVec3::new(0.7, 0.8, 0.9);
        tracker.tick_interpolation(&mut world);
        assert_eq!(
            world.ecs.get::<&Velocity>(player).unwrap().0,
            DVec3::new(0.7, 0.8, 0.9)
        );

        assert!(tracker.apply_metadata(
            &mut world,
            1,
            &vec![MetadataEntry {
                index: 6,
                value: Wire::Float(20.0),
            }],
        ));
        tracker.tick_interpolation(&mut world);
        assert_eq!(
            (
                tracker.get(1).unwrap().width,
                tracker.get(1).unwrap().height
            ),
            (0.6, 1.8),
            "healing restores the live player box"
        );
        assert!(tracker.apply_status_in_world(&world, 1, 3));
        assert_eq!(
            (
                tracker.get(1).unwrap().width,
                tracker.get(1).unwrap().height
            ),
            (0.2, 0.2),
            "a later death is a fresh edge"
        );
    }

    /// java: `EntityLivingBase.swingItem` + `updateArmSwingProgress` — six ticks from `-1` back
    /// to zero, with `swingProgress = swingProgressInt / 6`.
    #[test]
    fn an_arm_swing_runs_for_six_ticks_and_then_stops() {
        let mut world = World::new();
        let mut tracker = EntityTracker::new();
        spawn_at(&mut tracker, &mut world, 1, [0, 0, 0]);
        assert!(tracker.apply_swing(1));

        let mut seen = Vec::new();
        for _ in 0..8 {
            tracker.tick_interpolation(&mut world);
            seen.push(tracker.get(1).unwrap().render.swing_progress);
        }
        // -1 -> 0, 1, 2, 3, 4, 5, then 6 >= 6 resets to 0 and clears the flag.
        let want = [
            0.0,
            1.0 / 6.0,
            2.0 / 6.0,
            3.0 / 6.0,
            4.0 / 6.0,
            5.0 / 6.0,
            0.0,
            0.0,
        ];
        for (got, want) in seen.iter().zip(want) {
            assert!((got - want).abs() < 1e-6, "{seen:?}");
        }
    }

    /// F-P1-entity-06-6: `getArmSwingAnimationEnd` is queried on every swing update, not frozen
    /// when S0B starts the animation. Haste wins over Fatigue, and S1E changes the denominator
    /// part-way through the same remote swing.
    #[test]
    fn remote_haste_and_fatigue_change_the_live_swing_length_and_reset_on_id_reuse() {
        let mut world = World::new();
        let mut tracker = EntityTracker::new();
        spawn_at(&mut tracker, &mut world, 1, [0, 0, 0]);

        assert!(tracker.apply_effect(1, 4, 1)); // Fatigue II: 6 + 2 * 2 = 10.
        assert!(tracker.apply_effect(1, 3, 2)); // Haste III: 6 - 3 = 3.
        assert!(tracker.apply_effect(1, 3, 0)); // weaker refresh must not replace III.
        assert!(tracker.apply_swing(1));

        tracker.tick_interpolation(&mut world); // -1 -> 0 / 3
        tracker.tick_interpolation(&mut world); //  0 -> 1 / 3
        assert!((tracker.get(1).unwrap().render.swing_progress - 1.0 / 3.0).abs() < 1e-6);

        assert!(tracker.remove_effect(1, 3));
        tracker.tick_interpolation(&mut world); // 1 -> 2 / 10 (Fatigue now owns the duration).
        assert!((tracker.get(1).unwrap().render.swing_progress - 0.2).abs() < 1e-6);

        assert!(tracker.remove_effect(1, 4));
        tracker.tick_interpolation(&mut world); // 2 -> 3 / 6.
        assert!((tracker.get(1).unwrap().render.swing_progress - 0.5).abs() < 1e-6);

        // A replacement Java object with the same network id owns a fresh activePotionsMap.
        spawn_at(&mut tracker, &mut world, 1, [0, 0, 0]);
        assert!(tracker.apply_swing(1));
        tracker.tick_interpolation(&mut world);
        tracker.tick_interpolation(&mut world);
        assert!(
            (tracker.get(1).unwrap().render.swing_progress - 1.0 / 6.0).abs() < 1e-6,
            "same-id replacement must not inherit Haste or Fatigue"
        );
    }

    /// Negative control for F-P1-entity.monster-07-6. `swingItem()` exists on every
    /// `EntityLivingBase`, but only `EntityMob` and players call `updateArmSwingProgress` in
    /// 1.8.9. An iron golem therefore remains at zero while a zombie advances on the same S0B
    /// animation packet; the former used to animate under mc-rs's unconditional tick.
    #[test]
    fn only_entity_mobs_and_players_advance_arm_swing_progress() {
        let mut world = World::new();
        let mut tracker = EntityTracker::new();
        spawn_species(&mut tracker, &mut world, 1, EntityType::VillagerGolem, 0.0);
        spawn_species(&mut tracker, &mut world, 2, EntityType::Zombie, 0.0);
        assert!(tracker.apply_swing(1));
        assert!(tracker.apply_swing(2));

        tracker.tick_interpolation(&mut world); // both `-1`; zombie advances to 0
        tracker.tick_interpolation(&mut world); // zombie advances to 1/6

        assert_eq!(tracker.get(1).unwrap().render.swing_progress, 0.0);
        assert!(
            (tracker.get(2).unwrap().render.swing_progress - 1.0 / 6.0).abs() < 1e-6,
            "the EntityMob call site must still run"
        );
    }

    /// java: `EntityIronGolem.handleStatusUpdate` (`:190`) sets `attackTimer = 10` on status
    /// opcode 4 and `onLivingUpdate` (`:123`) counts it down. `EntityAnimState::attack_timer` is
    /// read by `ModelIronGolem` (`:100`) and had no source at all: the golem's overhead swing is
    /// the one attack animation `S0BPacketAnimation` never carries.
    #[test]
    fn the_iron_golems_attack_timer_comes_from_status_opcode_four() {
        let mut world = World::new();
        let mut tracker = EntityTracker::new();
        let golem = TrackedKind::Type(entity_type(99).expect("VillagerGolem"));
        tracker.spawn(
            &mut world,
            1,
            golem,
            None,
            [0, 0, 0],
            0.0,
            0.0,
            DVec3::ZERO,
            Metadata::new(),
        );
        assert_eq!(tracker.get(1).unwrap().render.entity.attack_timer, 0.0);
        assert!(tracker.apply_status(1, 4));
        assert!(
            tracker.take_status_effect_events().is_empty(),
            "golem status 4 is path-A/S29-covered, not a second local sound"
        );
        assert_eq!(tracker.get(1).unwrap().render.entity.attack_timer, 10.0);

        // One tick per decrement, floored at zero rather than running negative.
        for expected in (0..10).rev() {
            tracker.tick_interpolation(&mut world);
            assert_eq!(
                tracker.get(1).unwrap().render.entity.attack_timer,
                expected as f32
            );
        }
        tracker.tick_interpolation(&mut world);
        assert_eq!(tracker.get(1).unwrap().render.entity.attack_timer, 0.0);

        // java: `handleStatusUpdate`'s remaining opcodes fall through to sounds and particles
        // this does not draw, so they are refused rather than silently mis-handled. Opcode 11
        // used to be in this list; it is `EntityIronGolem`'s `holdRoseTick = 400` and is now
        // handled — see `the_iron_golems_poppy_latches_on_status_eleven_and_counts_down`.
        assert!(!tracker.apply_status(1, 6));
    }

    /// F-P1-entity.monster-07-5: `EntityIronGolem.onLivingUpdate` samples the block 0.2 below
    /// its feet and carries `Block.getStateId` as BLOCK_CRACK's one factory argument. Exercise
    /// the ordered tracker tick so a helper that exists but is never called cannot satisfy this.
    #[test]
    fn a_walking_iron_golem_emits_the_exact_underfoot_block_crack_payload() {
        let mut world = resident_test_world();
        let mut tracker = EntityTracker::new();
        let position = DVec3::new(1.0, 64.0, -1.0);
        let entity = tracker.spawn(
            &mut world,
            1,
            TrackedKind::Type(EntityType::VillagerGolem),
            None,
            [32, 64 * 32, -32],
            0.0,
            0.0,
            DVec3::new(0.1, 0.0, 0.0),
            Metadata::new(),
        );
        let underfoot = BlockPos::new(1, 63, -1);
        let stone = BlockState::new(block_by_name("stone").unwrap(), 0);
        let dirt = BlockState::new(block_by_name("dirt").unwrap(), 0);
        let seed = (0_i64..10_000)
            .find(|&seed| {
                let mut random = JavaRandom::new(seed);
                random.next_i32_bound(1000);
                random.next_i32_bound(5) == 0
            })
            .expect("a bounded seed with a successful one-in-five draw");

        let expected_for = |state: BlockState| {
            let mut random = JavaRandom::new(seed);
            let _ = random.next_i32_bound(1000);
            assert_eq!(random.next_i32_bound(5), 0);
            EntityParticleEvent {
                particle_id: BLOCK_CRACK,
                position: DVec3::new(
                    position.x
                        + (f64::from(random.next_f32()) - 0.5)
                            * f64::from(EntityType::VillagerGolem.info().width),
                    position.y + 0.1,
                    position.z
                        + (f64::from(random.next_f32()) - 0.5)
                            * f64::from(EntityType::VillagerGolem.info().width),
                ),
                velocity: DVec3::new(
                    4.0 * (f64::from(random.next_f32()) - 0.5),
                    0.5,
                    4.0 * (f64::from(random.next_f32()) - 0.5),
                ),
                args: EntityParticleArgs::block_state(state.to_java_state_id()),
            }
        };

        world.set_block(underfoot, stone);
        tracker.by_network_id.get_mut(&1).unwrap().particle_random = JavaRandom::new(seed);
        tracker.tick_interpolation(&mut world);
        assert_eq!(tracker.take_particle_events(), vec![expected_for(stone)]);

        world.set_block(underfoot, dirt);
        tracker.by_network_id.get_mut(&1).unwrap().particle_random = JavaRandom::new(seed);
        tracker.tick_interpolation(&mut world);
        let dirt_event = tracker.take_particle_events();
        assert_eq!(dirt_event, vec![expected_for(dirt)]);
        assert_ne!(
            EntityParticleArgs::block_state(stone.to_java_state_id()),
            dirt_event[0].args,
            "the packed underfoot state must not be erased or hard-coded"
        );

        world.set_block(underfoot, BlockState::AIR);
        tracker.by_network_id.get_mut(&1).unwrap().particle_random = JavaRandom::new(seed);
        tracker.tick_interpolation(&mut world);
        assert!(tracker.take_particle_events().is_empty());

        world.set_block(underfoot, stone);
        world.ecs.get::<&mut Velocity>(entity).unwrap().0 = DVec3::ZERO;
        let initial_random = JavaRandom::new(seed);
        tracker.by_network_id.get_mut(&1).unwrap().particle_random = initial_random.clone();
        tracker.tick_interpolation(&mut world);
        assert!(tracker.take_particle_events().is_empty());
        let mut expected_after_scheduler = initial_random.clone();
        expected_after_scheduler.next_i32_bound(1000);
        assert_eq!(
            tracker.get(1).unwrap().particle_random.raw_seed(),
            expected_after_scheduler.raw_seed(),
            "stationary golems consume the ambient scheduler draw but not the underfoot particle chance"
        );
    }

    /// java: `Entity.spawnRunningParticles`/`createRunningParticles` (`Entity.java:1165-1184`).
    /// This pins the base producer's offset draw order (there is no chance draw: the gate is only
    /// `isSprinting() && !isInWater()`), its deterministic `-motion*4` velocity, the packed
    /// underfoot state and the three omission gates that are easy to accidentally collapse into
    /// one material check.
    #[test]
    fn sprint_running_dust_uses_ordered_rng_state_tint_and_negative_gates() {
        let mut world = resident_test_world();
        let mut tracker = EntityTracker::new();
        let mut metadata = Metadata::new();
        metadata.set(0, mc_world::entity::MetadataValue::Byte(1 << 3));
        let position = DVec3::new(1.0, 64.0, -1.0);
        let velocity = DVec3::new(0.1, 0.0, -0.2);
        tracker.spawn(
            &mut world,
            7,
            TrackedKind::Type(EntityType::Zombie),
            None,
            [32, 64 * 32, -32],
            0.0,
            0.0,
            velocity,
            metadata,
        );
        let underfoot = BlockPos::new(1, 63, -1);
        let stone = BlockState::new(block_by_name("stone").unwrap(), 0);
        let dirt = BlockState::new(block_by_name("dirt").unwrap(), 0);
        let seed = 0x5EED_i64;

        world.set_block(underfoot, stone);
        tracker
            .particle_random_mut(7)
            .unwrap()
            .clone_from(&JavaRandom::new(seed));
        let mut oracle = JavaRandom::new(seed);
        let expected = EntityParticleEvent {
            particle_id: BLOCK_CRACK,
            position: DVec3::new(
                position.x
                    + (f64::from(oracle.next_f32()) - 0.5)
                        * f64::from(EntityType::Zombie.info().width),
                position.y + 0.1,
                position.z
                    + (f64::from(oracle.next_f32()) - 0.5)
                        * f64::from(EntityType::Zombie.info().width),
            ),
            velocity: DVec3::new(-velocity.x * 4.0, 1.5, -velocity.z * 4.0),
            args: EntityParticleArgs::block_state(stone.to_java_state_id()),
        };
        tracker.tick_interpolation(&mut world);
        assert_eq!(tracker.take_particle_events(), vec![expected]);
        // The two offsets are the tick's first draws. `EntityLiving.onEntityUpdate` reaches its
        // ambient `nextInt(1000)` only after `super.onEntityUpdate()` has run the running hook.
        oracle.next_i32_bound(1000);
        assert_eq!(
            tracker.get(7).unwrap().particle_random.raw_seed(),
            oracle.raw_seed(),
            "running dust draws exactly two floats, then the ambient scheduler draws"
        );

        // A different solid state updates the tint/state-id argument without changing the draw
        // recipe, while an air block is omitted before the offset draws.
        world.set_block(underfoot, dirt);
        *tracker.particle_random_mut(7).unwrap() = JavaRandom::new(seed);
        tracker.tick_interpolation(&mut world);
        let dirt_events = tracker.take_particle_events();
        assert_eq!(dirt_events.len(), 1);
        assert_eq!(
            dirt_events[0].args,
            EntityParticleArgs::block_state(dirt.to_java_state_id())
        );
        world.set_block(underfoot, BlockState::AIR);
        *tracker.particle_random_mut(7).unwrap() = JavaRandom::new(seed);
        tracker.tick_interpolation(&mut world);
        assert!(tracker.take_particle_events().is_empty());

        // Invisible blocks fail Java's `getRenderType() != -1` even though they are not air.
        let barrier = BlockState::new(block_by_name("barrier").unwrap(), 0);
        world.set_block(underfoot, barrier);
        *tracker.particle_random_mut(7).unwrap() = JavaRandom::new(seed);
        tracker.tick_interpolation(&mut world);
        assert!(tracker.take_particle_events().is_empty());

        // Previous-tick in-water suppression occurs before the block sample and offset draws,
        // preserving the entity RNG stream as well as the omitted effect.
        world.set_block(underfoot, stone);
        let before = JavaRandom::new(seed);
        *tracker.particle_random_mut(7).unwrap() = before.clone();
        tracker.by_network_id.get_mut(&7).unwrap().running_in_water = true;
        tracker.tick_interpolation(&mut world);
        assert!(tracker.take_particle_events().is_empty());
        let mut expected_after_scheduler = before.clone();
        expected_after_scheduler.next_i32_bound(1000);
        assert_eq!(
            tracker.get(7).unwrap().particle_random.raw_seed(),
            expected_after_scheduler.raw_seed()
        );
    }

    /// java: `Entity.onEntityUpdate` runs `spawnRunningParticles` on every tick for an
    /// `EntityOtherPlayerMP` too (`Entity.java:479`), gated only by the sprint flag and the
    /// previous water state. A remote player's motion changes only on S12, so it is normally zero
    /// while the sprint bit is set; the dust must still appear on every tick, with velocity
    /// `(0, 1.5, 0)`, drawing exactly two floats from the player's `Entity.rand` each time.
    #[test]
    fn a_sprinting_remote_player_with_zero_motion_emits_running_dust_every_tick() {
        use mc_protocol::{MetadataEntry, MetadataValue as Wire};

        let mut world = resident_test_world();
        let mut tracker = EntityTracker::new();
        let mut metadata = Metadata::new();
        metadata.set(0, mc_world::entity::MetadataValue::Byte(1 << 3));
        tracker.spawn(
            &mut world,
            9,
            TrackedKind::Player,
            Some(Uuid::from_u128(9)),
            [48, 64 * 32, -48],
            0.0,
            0.0,
            DVec3::ZERO,
            metadata,
        );
        let position = DVec3::new(1.5, 64.0, -1.5);
        let stone = BlockState::new(block_by_name("stone").unwrap(), 0);
        world.set_block(BlockPos::new(1, 63, -2), stone);
        let width = f64::from(tracker.get(9).unwrap().width);
        assert_eq!(width, f64::from(0.6_f32), "EntityPlayer is 0.6 wide");
        let seed = 0x0B0B_i64;
        *tracker.particle_random_mut(9).unwrap() = JavaRandom::new(seed);
        let mut oracle = JavaRandom::new(seed);

        for tick in 0..3 {
            tracker.tick_interpolation(&mut world);
            let expected = EntityParticleEvent {
                particle_id: BLOCK_CRACK,
                position: DVec3::new(
                    position.x + (f64::from(oracle.next_f32()) - 0.5) * width,
                    position.y + 0.1,
                    position.z + (f64::from(oracle.next_f32()) - 0.5) * width,
                ),
                velocity: DVec3::new(0.0, 1.5, 0.0),
                args: EntityParticleArgs::block_state(stone.to_java_state_id()),
            };
            assert_eq!(
                tracker.take_particle_events(),
                vec![expected],
                "tick {tick}"
            );
            assert_eq!(
                tracker.get(9).unwrap().particle_random.raw_seed(),
                oracle.raw_seed(),
                "tick {tick}: two offset floats and nothing else"
            );
        }

        // Clearing the sprint bit closes the only gate.
        assert!(tracker.apply_metadata(
            &mut world,
            9,
            &vec![MetadataEntry {
                index: 0,
                value: Wire::Byte(0),
            }],
        ));
        tracker.tick_interpolation(&mut world);
        assert!(tracker.take_particle_events().is_empty());
        assert_eq!(
            tracker.get(9).unwrap().particle_random.raw_seed(),
            oracle.raw_seed()
        );
    }

    /// java: the `motion² > 2.5E-7 && rand.nextInt(5) == 0` walking dust is the iron golem's own
    /// `onLivingUpdate` recipe (`EntityIronGolem.java:133-145`), not the base running gate, and
    /// the base hook does not borrow it. A sprint-flagged golem standing still gets the ungated
    /// base dust but neither walking dust nor a chance draw. Moving, it gets both, in Java's
    /// order: base dust (`Entity.onEntityUpdate`), the `EntityLiving` ambient `nextInt(1000)`,
    /// then the golem's own chance and four payload floats.
    #[test]
    fn an_iron_golem_keeps_its_own_gated_walking_dust_beside_the_base_running_hook() {
        let mut world = resident_test_world();
        let mut tracker = EntityTracker::new();
        let mut metadata = Metadata::new();
        metadata.set(0, mc_world::entity::MetadataValue::Byte(1 << 3));
        let position = DVec3::new(1.0, 64.0, -1.0);
        let entity = tracker.spawn(
            &mut world,
            1,
            TrackedKind::Type(EntityType::VillagerGolem),
            None,
            [32, 64 * 32, -32],
            0.0,
            0.0,
            DVec3::ZERO,
            metadata,
        );
        let stone = BlockState::new(block_by_name("stone").unwrap(), 0);
        world.set_block(BlockPos::new(1, 63, -1), stone);
        let width = f64::from(EntityType::VillagerGolem.info().width);
        let base_dust = |oracle: &mut JavaRandom, velocity: DVec3| EntityParticleEvent {
            particle_id: BLOCK_CRACK,
            position: DVec3::new(
                position.x + (f64::from(oracle.next_f32()) - 0.5) * width,
                position.y + 0.1,
                position.z + (f64::from(oracle.next_f32()) - 0.5) * width,
            ),
            velocity: DVec3::new(-velocity.x * 4.0, 1.5, -velocity.z * 4.0),
            args: EntityParticleArgs::block_state(stone.to_java_state_id()),
        };

        let still_seed = 0x601E_i64;
        *tracker.particle_random_mut(1).unwrap() = JavaRandom::new(still_seed);
        let mut oracle = JavaRandom::new(still_seed);
        let expected = base_dust(&mut oracle, DVec3::ZERO);
        oracle.next_i32_bound(1000);
        tracker.tick_interpolation(&mut world);
        assert_eq!(tracker.take_particle_events(), vec![expected]);
        assert_eq!(
            tracker.get(1).unwrap().particle_random.raw_seed(),
            oracle.raw_seed(),
            "a still golem's motion gate skips its nextInt(5)"
        );

        let velocity = DVec3::new(0.1, 0.0, 0.0);
        world.ecs.get::<&mut Velocity>(entity).unwrap().0 = velocity;
        let moving_seed = (0_i64..10_000)
            .find(|&seed| {
                let mut random = JavaRandom::new(seed);
                random.next_f32();
                random.next_f32();
                random.next_i32_bound(1000);
                random.next_i32_bound(5) == 0
            })
            .expect("a successful golem chance after the base dust and ambient draws");
        *tracker.particle_random_mut(1).unwrap() = JavaRandom::new(moving_seed);
        let mut oracle = JavaRandom::new(moving_seed);
        let base = base_dust(&mut oracle, velocity);
        oracle.next_i32_bound(1000);
        assert_eq!(oracle.next_i32_bound(5), 0);
        let walking = EntityParticleEvent {
            particle_id: BLOCK_CRACK,
            position: DVec3::new(
                position.x + (f64::from(oracle.next_f32()) - 0.5) * width,
                position.y + 0.1,
                position.z + (f64::from(oracle.next_f32()) - 0.5) * width,
            ),
            velocity: DVec3::new(
                4.0 * (f64::from(oracle.next_f32()) - 0.5),
                0.5,
                4.0 * (f64::from(oracle.next_f32()) - 0.5),
            ),
            args: EntityParticleArgs::block_state(stone.to_java_state_id()),
        };
        tracker.tick_interpolation(&mut world);
        assert_eq!(tracker.take_particle_events(), vec![base, walking]);
        assert_eq!(
            tracker.get(1).unwrap().particle_random.raw_seed(),
            oracle.raw_seed()
        );
    }

    /// java: `EntityRabbit` overrides `spawnRunningParticles` with an empty body
    /// (`EntityRabbit.java:211-213`), so a sprint-flagged rabbit gets no per-tick dust. Its
    /// `handleStatusUpdate(1)` (`:491-498`) still calls the inherited `createRunningParticles`
    /// body directly: one ungated dust, two floats from the rabbit's `Entity.rand`, and nothing
    /// (not even a draw) over a `getRenderType() == -1` block.
    #[test]
    fn rabbit_status_one_emits_inherited_running_dust_but_its_tick_hook_is_empty() {
        let mut world = resident_test_world();
        let mut tracker = EntityTracker::new();
        let mut metadata = Metadata::new();
        metadata.set(0, mc_world::entity::MetadataValue::Byte(1 << 3));
        let entity = tracker.spawn(
            &mut world,
            3,
            TrackedKind::Type(EntityType::Rabbit),
            None,
            [32, 64 * 32, -32],
            0.0,
            0.0,
            DVec3::new(0.05, 0.0, 0.025),
            metadata,
        );
        let underfoot = BlockPos::new(1, 63, -1);
        let stone = BlockState::new(block_by_name("stone").unwrap(), 0);
        world.set_block(underfoot, stone);

        tracker.tick_interpolation(&mut world);
        assert!(
            tracker.take_particle_events().is_empty(),
            "the rabbit's spawnRunningParticles override is empty"
        );

        let position = world.ecs.get::<&Position>(entity).unwrap().0;
        let velocity = world.ecs.get::<&Velocity>(entity).unwrap().0;
        let width = f64::from(tracker.get(3).unwrap().width);
        let seed = 0x4AB1_i64;
        *tracker.particle_random_mut(3).unwrap() = JavaRandom::new(seed);
        let mut oracle = JavaRandom::new(seed);
        let expected = EntityParticleEvent {
            particle_id: BLOCK_CRACK,
            position: DVec3::new(
                position.x + (f64::from(oracle.next_f32()) - 0.5) * width,
                position.y + 0.1,
                position.z + (f64::from(oracle.next_f32()) - 0.5) * width,
            ),
            velocity: DVec3::new(-velocity.x * 4.0, 1.5, -velocity.z * 4.0),
            args: EntityParticleArgs::block_state(stone.to_java_state_id()),
        };
        assert!(tracker.apply_status_in_world(&world, 3, 1));
        assert_eq!(tracker.take_particle_events(), vec![expected]);
        assert_eq!(
            tracker.get(3).unwrap().particle_random.raw_seed(),
            oracle.raw_seed()
        );
        assert_eq!(tracker.get(3).unwrap().rabbit_jump_state(), Some((0, 10)));

        world.set_block(underfoot, BlockState::AIR);
        assert!(tracker.apply_status_in_world(&world, 3, 1));
        assert!(tracker.take_particle_events().is_empty());
        assert_eq!(
            tracker.get(3).unwrap().particle_random.raw_seed(),
            oracle.raw_seed()
        );
    }

    /// java: `EnchantmentHelper.applyThornEnchantments(remotePlayer, localPlayer)`
    /// (`EnchantmentHelper.java:223-237`) visits boots..helmet and then the held item; only
    /// `EnchantmentThorns.onUserHurt` (`EnchantmentThorns.java:55-87`) acts. The roll and the
    /// discarded `1 + nextInt(4)` come from the target's `Entity.rand`, the hit requests the
    /// local `damage.thorns`, and the first thorns armour piece takes `damageItem(3)` (a miss,
    /// `damageItem(1)`), with Unbreaking's armour draws on the same stream.
    #[test]
    fn thorns_on_a_remote_player_rolls_its_stream_and_requests_the_local_sound() {
        let mut world = World::new();
        let mut tracker = EntityTracker::new();
        tracker.spawn(
            &mut world,
            5,
            TrackedKind::Player,
            Some(Uuid::from_u128(5)),
            [0, 64 * 32, 0],
            0.0,
            0.0,
            DVec3::ZERO,
            Metadata::new(),
        );
        let enchanted = |name: &str, enchantments: &[(i16, i16)]| {
            let list = enchantments
                .iter()
                .map(|&(id, level)| {
                    let mut entry = mc_nbt::NbtCompound::new();
                    entry.insert("id", mc_nbt::Nbt::Short(id));
                    entry.insert("lvl", mc_nbt::Nbt::Short(level));
                    mc_nbt::Nbt::Compound(entry)
                })
                .collect();
            let mut nbt = mc_nbt::NbtCompound::new();
            nbt.insert("ench", mc_nbt::Nbt::list(list));
            mc_protocol::ItemStack {
                item_id: mc_data::item_by_name(name).expect("known item").0 as i16,
                count: 1,
                damage: 0,
                nbt: Some(nbt),
            }
        };
        let attacker = DVec3::new(2.0, 64.0, 0.5);
        let thorns_sound = EntityStatusEffectEvent::Sound(EntityStatusSoundEvent {
            network_id: 77,
            source_entity: None,
            name: "damage.thorns",
            volume: 0.5,
            pitch: 1.0,
            first_random: 0.0,
            second_random: 0.0,
            position: Some(attacker),
            far_name: None,
        });

        // No thorns anywhere: no draws and no request.
        assert!(tracker.apply_equipment(5, 3, Some(enchanted("diamond_chestplate", &[(0, 4)]))));
        let quiet = tracker.get(5).unwrap().particle_random.raw_seed();
        assert_eq!(tracker.apply_local_attack_thorns(5, 77, attacker), 0);
        assert_eq!(tracker.get(5).unwrap().particle_random.raw_seed(), quiet);

        // Thorns III + Unbreaking III chestplate, hit: roll, damage draw, then three armour
        // points, each `nextFloat() < 0.6F` or else `nextInt(4) > 0` to negate it.
        let chestplate = enchanted("diamond_chestplate", &[(7, 3), (34, 3)]);
        assert!(tracker.apply_equipment(5, 3, Some(chestplate.clone())));
        let hit_seed = (0_i64..)
            .find(|&seed| JavaRandom::new(seed).next_f32() < 0.45)
            .unwrap();
        *tracker.particle_random_mut(5).unwrap() = JavaRandom::new(hit_seed);
        let mut oracle = JavaRandom::new(hit_seed);
        assert!(oracle.next_f32() < 0.45);
        oracle.next_i32_bound(4);
        let mut applied = 0;
        for _ in 0..3 {
            if oracle.next_f32() < 0.6 || oracle.next_i32_bound(4) == 0 {
                applied += 1;
            }
        }
        assert_eq!(tracker.apply_local_attack_thorns(5, 77, attacker), 1);
        assert_eq!(tracker.take_status_effect_events(), vec![thorns_sound]);
        assert_eq!(
            tracker.get(5).unwrap().particle_random.raw_seed(),
            oracle.raw_seed()
        );
        assert_eq!(
            tracker.get(5).unwrap().equipment[3]
                .as_ref()
                .unwrap()
                .damage,
            applied
        );

        // Miss: only the roll, then `damageItem(1)` on the same chestplate.
        assert!(tracker.apply_equipment(5, 3, Some(chestplate)));
        let miss_seed = (0_i64..)
            .find(|&seed| JavaRandom::new(seed).next_f32() >= 0.45)
            .unwrap();
        *tracker.particle_random_mut(5).unwrap() = JavaRandom::new(miss_seed);
        let mut oracle = JavaRandom::new(miss_seed);
        oracle.next_f32();
        let applied = i16::from(oracle.next_f32() < 0.6 || oracle.next_i32_bound(4) == 0);
        assert_eq!(tracker.apply_local_attack_thorns(5, 77, attacker), 0);
        assert!(tracker.take_status_effect_events().is_empty());
        assert_eq!(
            tracker.get(5).unwrap().particle_random.raw_seed(),
            oracle.raw_seed()
        );
        assert_eq!(
            tracker.get(5).unwrap().equipment[3]
                .as_ref()
                .unwrap()
                .damage,
            applied
        );

        // A Thorns sword is visited last, as the held item. `getEnchantedItem` searches armour
        // only, so with no thorns armour the hit damages nothing but still requests the sound.
        assert!(tracker.apply_equipment(5, 3, None));
        assert!(tracker.apply_equipment(5, 0, Some(enchanted("diamond_sword", &[(7, 3)]))));
        *tracker.particle_random_mut(5).unwrap() = JavaRandom::new(hit_seed);
        assert_eq!(tracker.apply_local_attack_thorns(5, 77, attacker), 1);
        assert_eq!(tracker.take_status_effect_events(), vec![thorns_sound]);
        assert_eq!(
            tracker.get(5).unwrap().equipment[0]
                .as_ref()
                .unwrap()
                .damage,
            0
        );
        let mut oracle = JavaRandom::new(hit_seed);
        oracle.next_f32();
        oracle.next_i32_bound(4);
        assert_eq!(
            tracker.get(5).unwrap().particle_random.raw_seed(),
            oracle.raw_seed()
        );
    }

    /// `EntityHorse.handleStatusUpdate` turns status 7 into seven HEART particles and status 6
    /// into seven SMOKE_NORMAL particles.  The particle position draws follow each particle's
    /// three Gaussian velocity draws, just as vanilla's `spawnHorseParticles` loop does.
    #[test]
    fn horse_taming_statuses_emit_their_client_particle_bursts() {
        let mut world = World::new();
        let mut tracker = EntityTracker::new();
        let horse = TrackedKind::Type(EntityType::EntityHorse);
        let entity = tracker.spawn(
            &mut world,
            1,
            horse,
            None,
            [32, 64 * 32, -32],
            0.0,
            0.0,
            DVec3::ZERO,
            Metadata::new(),
        );
        tracker.by_network_id.get_mut(&1).unwrap().particle_random = JavaRandom::new(0xBEEF);

        let mut expected_random = JavaRandom::new(0xBEEF);
        let expected_velocity = DVec3::new(
            expected_random.next_gaussian() * 0.02,
            expected_random.next_gaussian() * 0.02,
            expected_random.next_gaussian() * 0.02,
        );
        let expected_offset = DVec3::new(
            f64::from(
                expected_random.next_f32() * EntityType::EntityHorse.info().width * 2.0
                    - EntityType::EntityHorse.info().width,
            ),
            0.5 + f64::from(expected_random.next_f32() * EntityType::EntityHorse.info().height),
            f64::from(
                expected_random.next_f32() * EntityType::EntityHorse.info().width * 2.0
                    - EntityType::EntityHorse.info().width,
            ),
        );

        assert!(tracker.apply_status(1, 7));
        let bursts = tracker.take_particle_events();
        assert_eq!(bursts.len(), 7);
        assert_eq!(bursts[0].particle_id, HEART);
        assert_eq!(
            bursts[0].position,
            DVec3::new(1.0, 64.0, -1.0) + expected_offset
        );
        assert_eq!(bursts[0].velocity, expected_velocity);

        assert!(tracker.apply_status(1, 6));
        let smoke = tracker.take_particle_events();
        assert_eq!(smoke.len(), 7);
        assert!(smoke.iter().all(|event| event.particle_id == SMOKE_NORMAL));
        assert_eq!(
            world.ecs.get::<&Position>(entity).unwrap().0,
            DVec3::new(1.0, 64.0, -1.0)
        );
    }

    /// java: `EntityTameable.playTameEffect` and `EntityAnimal.handleStatusUpdate(18)` each
    /// emit seven spread particles, with the same Gaussian-before-position draw order. Status
    /// bytes remain species-polymorphic: a zombie must not borrow the animal/tameable branches,
    /// and an absent network id must not create an orphaned burst.
    #[test]
    fn tameable_and_animal_statuses_emit_exact_particle_bursts_and_gate_species() {
        let mut world = World::new();
        let mut tracker = EntityTracker::new();
        spawn_species(&mut tracker, &mut world, 1, EntityType::Wolf, 0.0);
        spawn_species(&mut tracker, &mut world, 2, EntityType::Pig, 0.0);
        spawn_species(&mut tracker, &mut world, 3, EntityType::Zombie, 0.0);

        let seed = 0x51_7A_1E;
        tracker.by_network_id.get_mut(&1).unwrap().particle_random = JavaRandom::new(seed);
        let mut expected_random = JavaRandom::new(seed);
        let expected_velocity = DVec3::new(
            expected_random.next_gaussian() * 0.02,
            expected_random.next_gaussian() * 0.02,
            expected_random.next_gaussian() * 0.02,
        );
        let expected_position = DVec3::new(
            f64::from(
                expected_random.next_f32() * EntityType::Wolf.info().width * 2.0
                    - EntityType::Wolf.info().width,
            ),
            0.5 + f64::from(expected_random.next_f32() * EntityType::Wolf.info().height),
            f64::from(
                expected_random.next_f32() * EntityType::Wolf.info().width * 2.0
                    - EntityType::Wolf.info().width,
            ),
        );
        assert!(tracker.apply_status(1, 7));
        let tame = tracker.take_particle_events();
        assert_eq!(tame.len(), 7);
        assert!(tame.iter().all(|event| event.particle_id == HEART));
        assert_eq!(tame[0].position, expected_position);
        assert_eq!(tame[0].velocity, expected_velocity);

        assert!(tracker.apply_status(1, 6));
        let failed_tame = tracker.take_particle_events();
        assert_eq!(failed_tame.len(), 7);
        assert!(failed_tame
            .iter()
            .all(|event| event.particle_id == SMOKE_NORMAL));

        assert!(tracker.apply_status(2, 18));
        let love = tracker.take_particle_events();
        assert_eq!(love.len(), 7);
        assert!(love.iter().all(|event| event.particle_id == HEART));

        assert!(!tracker.apply_status(3, 6), "zombie is not EntityTameable");
        assert!(!tracker.apply_status(3, 18), "zombie is not EntityAnimal");
        assert!(
            !tracker.apply_status(99, 18),
            "unknown entity id must be rejected"
        );
        assert!(tracker.take_particle_events().is_empty());
    }

    /// java: `EntityVillager.spawnParticles` (`:714-727`) uses five particles and lifts their
    /// origin by one block. The three mood bytes select different particle ids but share the
    /// exact random/position shape; a non-villager or unknown id must fall through.
    #[test]
    fn villager_mood_statuses_emit_five_species_specific_particles() {
        let mut world = World::new();
        let mut tracker = EntityTracker::new();
        spawn_species(&mut tracker, &mut world, 1, EntityType::Villager, 0.0);
        spawn_species(&mut tracker, &mut world, 2, EntityType::Zombie, 0.0);

        for (opcode, particle_id) in [(12, HEART), (13, VILLAGER_ANGRY), (14, VILLAGER_HAPPY)] {
            tracker.by_network_id.get_mut(&1).unwrap().particle_random =
                JavaRandom::new(0xCAFE + i64::from(opcode));
            assert!(tracker.apply_status(1, opcode));
            let particles = tracker.take_particle_events();
            assert_eq!(particles.len(), 5, "opcode {opcode}");
            assert!(particles
                .iter()
                .all(|event| event.particle_id == particle_id));
            assert!(particles.iter().all(|event| {
                event.position.y >= 1.0
                    && event.position.y < 1.0 + f64::from(EntityType::Villager.info().height)
            }));
        }

        assert!(!tracker.apply_status(2, 12), "zombie is not a villager");
        assert!(!tracker.apply_status(1, 15), "villager has no witch status");
        assert!(
            !tracker.apply_status(99, 14),
            "unknown entity id must be rejected"
        );
        assert!(tracker.take_particle_events().is_empty());
    }

    /// java: `EntityWitch.handleStatusUpdate(15)` chooses `nextInt(35) + 10` once, then draws
    /// three Gaussian offsets per particle. This test locks both the count and first draw, so a
    /// future refactor cannot accidentally use the common width/height spread helper.
    #[test]
    fn witch_magic_status_preserves_count_and_gaussian_offsets() {
        let mut world = World::new();
        let mut tracker = EntityTracker::new();
        spawn_species(&mut tracker, &mut world, 1, EntityType::Witch, 0.0);
        spawn_species(&mut tracker, &mut world, 2, EntityType::Zombie, 0.0);

        let seed = 0x15_7A_7C;
        tracker.by_network_id.get_mut(&1).unwrap().particle_random = JavaRandom::new(seed);
        let mut expected_random = JavaRandom::new(seed);
        let expected_count = usize::try_from(expected_random.next_i32_bound(35) + 10).unwrap();
        let scale = 0.129_999_995_231_628_42;
        let expected_position = DVec3::new(
            expected_random.next_gaussian() * scale,
            f64::from(EntityType::Witch.info().height)
                + 0.5
                + expected_random.next_gaussian() * scale,
            expected_random.next_gaussian() * scale,
        );
        assert!(tracker.apply_status(1, 15));
        let particles = tracker.take_particle_events();
        assert_eq!(particles.len(), expected_count);
        assert!(particles.iter().all(|event| {
            event.particle_id == SPELL_WITCH
                && event.velocity == DVec3::ZERO
                && event.args.is_empty()
        }));
        assert_eq!(particles[0].position, expected_position);

        assert!(!tracker.apply_status(2, 15), "zombie is not a witch");
        assert!(
            !tracker.apply_status(99, 15),
            "unknown entity id must be rejected"
        );
        assert!(tracker.take_particle_events().is_empty());
    }

    /// java: `EntityLiving.spawnExplosionParticle` (`:244-261`) belongs to the concrete
    /// `EntityLiving` family, not every `EntityLivingBase`. Keep its twenty-particle Gaussian
    /// displacement exact and reject a projectile that merely shares the status byte.
    #[test]
    fn living_explosion_status_preserves_java_order_and_entity_family() {
        let mut world = World::new();
        let mut tracker = EntityTracker::new();
        spawn_species(&mut tracker, &mut world, 1, EntityType::Silverfish, 0.0);
        spawn_species(&mut tracker, &mut world, 2, EntityType::Fireball, 0.0);

        let seed = 0x20_EF;
        tracker.by_network_id.get_mut(&1).unwrap().particle_random = JavaRandom::new(seed);
        let mut expected_random = JavaRandom::new(seed);
        let d0 = expected_random.next_gaussian() * 0.02;
        let d1 = expected_random.next_gaussian() * 0.02;
        let d2 = expected_random.next_gaussian() * 0.02;
        let width = EntityType::Silverfish.info().width;
        let height = EntityType::Silverfish.info().height;
        let expected_position = DVec3::new(
            f64::from(expected_random.next_f32() * width * 2.0 - width) - d0 * 10.0,
            f64::from(expected_random.next_f32() * height) - d1 * 10.0,
            f64::from(expected_random.next_f32() * width * 2.0 - width) - d2 * 10.0,
        );
        assert!(tracker.apply_status(1, 20));
        let particles = tracker.take_particle_events();
        assert_eq!(particles.len(), 20);
        assert!(particles
            .iter()
            .all(|event| { event.particle_id == EXPLOSION_NORMAL && event.args.is_empty() }));
        assert_eq!(particles[0].position, expected_position);
        assert_eq!(particles[0].velocity, DVec3::new(d0, d1, d2));

        assert!(
            !tracker.apply_status(2, 20),
            "fireball inherits Entity, not EntityLiving"
        );
        assert!(
            !tracker.apply_status(99, 20),
            "unknown entity id must be rejected"
        );
        assert!(tracker.take_particle_events().is_empty());
    }

    /// java: `EntityZombie.handleStatusUpdate(16)` calls `World.playSound` directly on the
    /// client, unlike path-A hurt/death sounds. Preserve its two handler-specific random draws,
    /// and preserve the `isSilent` gate before those draws.
    #[test]
    fn zombie_conversion_status_queues_only_the_local_sound_path() {
        let mut world = World::new();
        let mut tracker = EntityTracker::new();
        spawn_species(&mut tracker, &mut world, 1, EntityType::Zombie, 0.0);
        spawn_species(&mut tracker, &mut world, 2, EntityType::Pig, 0.0);

        let seed = 0x16_5A_1D;
        tracker.by_network_id.get_mut(&1).unwrap().particle_random = JavaRandom::new(seed);
        let mut expected_random = JavaRandom::new(seed);
        let first_random = expected_random.next_f32();
        let second_random = expected_random.next_f32();
        let source_entity = tracker.get(1).unwrap().entity;
        assert!(tracker.apply_status_in_world(&world, 1, 16));
        let replacement_entity = tracker.spawn(
            &mut world,
            1,
            TrackedKind::Type(EntityType::Zombie),
            None,
            [10 * 32, 20 * 32, -5 * 32],
            0.0,
            0.0,
            DVec3::ZERO,
            Metadata::new(),
        );
        assert_ne!(source_entity, replacement_entity);
        let effects = tracker.take_status_effect_events();
        assert_eq!(effects.len(), 1);
        match effects[0] {
            EntityStatusEffectEvent::Sound(sound) => {
                assert_eq!(sound.network_id, 1);
                assert_eq!(sound.source_entity, Some(source_entity));
                assert_eq!(sound.position, Some(DVec3::new(0.5, 0.5, 0.5)));
                assert_eq!(sound.name, "mob.zombie.remedy");
                assert_eq!(sound.first_random.to_bits(), first_random.to_bits());
                assert_eq!(sound.second_random.to_bits(), second_random.to_bits());
                assert_eq!(sound.volume.to_bits(), (1.0 + first_random).to_bits());
                assert_eq!(sound.pitch.to_bits(), (second_random * 0.7 + 0.3).to_bits());
            }
        }
        assert!(tracker.take_particle_events().is_empty());

        assert!(!tracker.apply_status(2, 16), "pig is not a zombie");
        assert!(
            !tracker.apply_status(99, 16),
            "unknown entity id must be rejected"
        );
        assert!(tracker.take_status_effect_events().is_empty());

        set_meta(
            &mut tracker,
            &mut world,
            1,
            4,
            mc_protocol::MetadataValue::Byte(1),
        );
        tracker.by_network_id.get_mut(&1).unwrap().particle_random = JavaRandom::new(seed);
        assert!(tracker.apply_status(1, 16));
        assert!(tracker.take_status_effect_events().is_empty());
        let mut silent_random = JavaRandom::new(seed);
        assert_eq!(
            tracker
                .by_network_id
                .get_mut(&1)
                .unwrap()
                .particle_random
                .next_f32()
                .to_bits(),
            silent_random.next_f32().to_bits(),
            "silent conversion does not consume the local sound's random operands"
        );
    }

    /// S19's living hurt/death callbacks are path A: the client dispatches `Entity.playSound`
    /// into the empty `IWorldAccess.playSound` body, while the server-side attack/death path has
    /// already emitted S29. The status handler still evaluates Java's two-float pitch expression,
    /// so the entity RNG stream advances without creating a duplicate local event.
    #[test]
    fn status_hurt_and_death_use_server_s29_without_local_queue_but_keep_java_random_order() {
        use mc_protocol::{MetadataEntry, MetadataValue as Wire};

        let mut world = World::new();
        let mut tracker = EntityTracker::new();
        spawn_at(&mut tracker, &mut world, 1, [0, 0, 0]);
        tracker.by_network_id.get_mut(&1).unwrap().particle_random = JavaRandom::new(0xC0FFEE);

        assert!(tracker.apply_status(1, 2));
        assert!(
            tracker.take_status_effect_events().is_empty(),
            "status 2 must not duplicate the server's S29 hurt sound"
        );
        let mut want_random = JavaRandom::new(0xC0FFEE);
        want_random.next_f32();
        want_random.next_f32();
        assert_eq!(
            tracker
                .by_network_id
                .get_mut(&1)
                .unwrap()
                .particle_random
                .next_f32()
                .to_bits(),
            want_random.next_f32().to_bits(),
            "path-A status still evaluates both pitch operands"
        );

        // The death callback follows the same path and must also consume exactly two operands.
        tracker.by_network_id.get_mut(&1).unwrap().particle_random = JavaRandom::new(7);
        assert!(tracker.apply_status(1, 3));
        assert!(
            tracker.take_status_effect_events().is_empty(),
            "status 3 must not duplicate the server's S29 death sound"
        );
        let mut after_two = JavaRandom::new(7);
        after_two.next_f32();
        after_two.next_f32();
        assert_eq!(
            tracker
                .by_network_id
                .get_mut(&1)
                .unwrap()
                .particle_random
                .next_f32()
                .to_bits(),
            after_two.next_f32().to_bits(),
            "death's muted path-A sound still evaluated the vanilla pitch expression"
        );

        // `Entity.playSound` suppresses playback, not argument evaluation. A silent zombie
        // therefore advances the same two RNG draws but exposes no output event.
        assert!(tracker.apply_metadata(
            &mut world,
            1,
            &vec![MetadataEntry {
                index: 4,
                value: Wire::Byte(1),
            }],
        ));
        tracker.by_network_id.get_mut(&1).unwrap().particle_random = JavaRandom::new(11);
        assert!(tracker.apply_status(1, 2));
        assert!(tracker.take_status_effect_events().is_empty());
        let mut after_two = JavaRandom::new(11);
        after_two.next_f32();
        after_two.next_f32();
        assert_eq!(
            tracker
                .by_network_id
                .get_mut(&1)
                .unwrap()
                .particle_random
                .next_f32()
                .to_bits(),
            after_two.next_f32().to_bits(),
            "the muted sound still evaluated the vanilla pitch expression"
        );
    }

    /// java: `EntityGuardian.getHurtSound`/`getDeathSound` test the cached `inWater` bit before
    /// the elder watcher, while `EntityGuardian.getLivingSound` uses the same dry-first ordering.
    /// The generic living status path remains server-authoritative (no local S19 sound event), and
    /// unrelated animals, Endermen, and item frames retain their own status semantics.
    #[test]
    fn guardian_status_and_idle_sounds_follow_water_before_elder_without_cross_family_leakage() {
        let mut world = World::new();
        let mut guardian_metadata = Metadata::new();
        guardian_metadata.set(16, MetadataValue::Int(4));
        let mut tracker = EntityTracker::new();
        tracker.spawn(
            &mut world,
            1,
            TrackedKind::Type(EntityType::Guardian),
            None,
            [0, 0, 0],
            0.0,
            0.0,
            DVec3::ZERO,
            guardian_metadata,
        );

        let guardian = tracker
            .by_network_id
            .get_mut(&1)
            .expect("guardian generation");
        guardian.in_water = false;
        assert_eq!(
            living_status_sound(guardian, 2).map(|(name, _)| name),
            Some("mob.guardian.land.hit")
        );
        assert_eq!(
            living_status_sound(guardian, 3).map(|(name, _)| name),
            Some("mob.guardian.land.death")
        );
        guardian.in_water = true;
        guardian.status_sound_guardian_elder = false;
        assert_eq!(
            living_status_sound(guardian, 2).map(|(name, _)| name),
            Some("mob.guardian.hit")
        );
        assert_eq!(
            living_status_sound(guardian, 3).map(|(name, _)| name),
            Some("mob.guardian.death")
        );
        guardian.status_sound_guardian_elder = true;
        assert_eq!(
            living_status_sound(guardian, 2).map(|(name, _)| name),
            Some("mob.guardian.elder.hit")
        );
        assert_eq!(
            living_status_sound(guardian, 3).map(|(name, _)| name),
            Some("mob.guardian.elder.death")
        );

        let facts = LivingAmbientFacts {
            guardian_elder: true,
            ..LivingAmbientFacts::default()
        };
        let mut random = JavaRandom::new(1);
        assert_eq!(
            living_ambient_sound(
                TrackedKind::Type(EntityType::Guardian),
                facts,
                false,
                false,
                &mut random,
            )
            .map(|(name, _, _)| name),
            Some("mob.guardian.land.idle")
        );
        let mut random = JavaRandom::new(1);
        assert_eq!(
            living_ambient_sound(
                TrackedKind::Type(EntityType::Guardian),
                facts,
                true,
                false,
                &mut random,
            )
            .map(|(name, _, _)| name),
            Some("mob.guardian.elder.idle")
        );
        let mut random = JavaRandom::new(1);
        assert_eq!(
            living_ambient_sound(
                TrackedKind::Type(EntityType::Guardian),
                LivingAmbientFacts::default(),
                true,
                false,
                &mut random,
            )
            .map(|(name, _, _)| name),
            Some("mob.guardian.idle")
        );

        tracker.spawn(
            &mut world,
            2,
            TrackedKind::Type(EntityType::Enderman),
            None,
            [0, 0, 0],
            0.0,
            0.0,
            DVec3::ZERO,
            Metadata::new(),
        );
        let enderman = tracker
            .by_network_id
            .get_mut(&2)
            .expect("enderman generation");
        enderman.in_water = true;
        assert_eq!(
            living_status_sound(enderman, 2).map(|(name, _)| name),
            Some("mob.endermen.hit")
        );
        assert_eq!(
            living_status_sound(enderman, 3).map(|(name, _)| name),
            Some("mob.endermen.death")
        );

        tracker.spawn(
            &mut world,
            3,
            TrackedKind::Type(EntityType::Pig),
            None,
            [0, 0, 0],
            0.0,
            0.0,
            DVec3::ZERO,
            Metadata::new(),
        );
        let animal = tracker
            .by_network_id
            .get_mut(&3)
            .expect("animal generation");
        animal.in_water = true;
        assert_eq!(
            living_status_sound(animal, 2).map(|(name, _)| name),
            Some("mob.pig.say")
        );
        assert_eq!(
            classify_status(TrackedKind::Type(EntityType::ItemFrame), 2),
            StatusOpcodeClass::Noop,
            "item frames do not inherit EntityLivingBase hurt status"
        );

        let seed = 0x47_11;
        tracker
            .by_network_id
            .get_mut(&1)
            .expect("guardian generation")
            .particle_random = JavaRandom::new(seed);
        assert!(tracker.apply_status(1, 2));
        assert!(
            tracker.take_status_effect_events().is_empty(),
            "S19 hurt remains the server S29 sound path"
        );
        let mut expected = JavaRandom::new(seed);
        expected.next_f32();
        expected.next_f32();
        assert_eq!(
            tracker
                .by_network_id
                .get_mut(&1)
                .expect("guardian generation")
                .particle_random
                .next_f32()
                .to_bits(),
            expected.next_f32().to_bits(),
            "guardian status selection preserves the two pitch draws"
        );
    }

    /// java: `EntityAnimal.attackEntityFrom` clears its private `inLove` timer before the
    /// server-confirmed hurt status reaches the client. Status 18 is only the breeding particle
    /// callback and must not clear a locally seeded timer; a non-animal's generic hurt status must
    /// not borrow the animal-only reset either.
    #[test]
    fn animal_hurt_status_clears_server_love_timer_but_non_attack_controls_do_not() {
        let mut world = World::new();
        let mut tracker = EntityTracker::new();
        let mut metadata = Metadata::new();
        metadata.set(12, MetadataValue::Byte(0));
        let pig = tracker.spawn(
            &mut world,
            1,
            TrackedKind::Type(EntityType::Pig),
            None,
            [0, 0, 0],
            0.0,
            0.0,
            DVec3::ZERO,
            metadata,
        );

        // This is the local interaction prediction; it seeds the private client shadow but does
        // not itself represent a successful attack or damage event.
        assert!(tracker.apply_client_animal_feed(&mut world, 1, pig, true, false));
        assert_eq!(tracker.get(1).unwrap().animal_in_love, 600);
        assert!(!tracker
            .get(1)
            .unwrap()
            .animal_breeding_ready(&world)
            .unwrap());

        // EntityAnimal.handleStatusUpdate(18) only emits the seven-heart callback.
        assert!(tracker.apply_status(1, 18));
        assert_eq!(tracker.get(1).unwrap().animal_in_love, 600);
        assert_eq!(tracker.take_particle_events().len(), 7);

        // The S19 hurt packet is the server-authoritative attack edge and clears inLove before the
        // generic living hurt animation/RNG path runs.
        assert!(tracker.apply_status(1, 2));
        assert_eq!(tracker.get(1).unwrap().animal_in_love, 0);
        assert!(tracker
            .get(1)
            .unwrap()
            .animal_breeding_ready(&world)
            .unwrap());

        // The same numeric status on a non-animal remains the generic living hurt response.
        spawn_at(&mut tracker, &mut world, 2, [0, 0, 0]);
        tracker.by_network_id.get_mut(&2).unwrap().animal_in_love = 600;
        assert!(tracker.apply_status(2, 2));
        assert_eq!(tracker.get(2).unwrap().animal_in_love, 600);
    }

    /// Every byte emitted by the vanilla `setEntityState` call sites is classified by its entity
    /// family. These controls make it hard to regress to the tempting but wrong global
    /// `opcode == 10`/`opcode == 3` dispatch: a sheep, TNT cart, egg, generic projectile, and
    /// guardian all give the same packet shape different client behaviour.
    #[test]
    fn status_opcode_classification_is_entity_polymorphic_and_nonmatching_bytes_are_noops() {
        use EntityType as E;
        assert_eq!(
            classify_status(TrackedKind::Type(E::Rabbit), 1),
            StatusOpcodeClass::RabbitJump
        );
        assert_eq!(
            classify_status(TrackedKind::Type(E::Zombie), 2),
            StatusOpcodeClass::LivingHurt
        );
        assert_eq!(
            classify_status(TrackedKind::Type(E::ThrownEgg), 3),
            StatusOpcodeClass::Noop
        );
        assert_eq!(
            classify_status(TrackedKind::Type(E::Fireball), 3),
            StatusOpcodeClass::Noop,
            "a fireball inherits Entity's empty handler, not living death"
        );
        assert_eq!(
            classify_status(TrackedKind::Type(E::Sheep), 10),
            StatusOpcodeClass::SheepGraze
        );
        assert_eq!(
            classify_status(TrackedKind::Type(E::MinecartTNT), 10),
            StatusOpcodeClass::TntMinecartIgnite
        );
        assert_eq!(
            classify_status(TrackedKind::Type(E::Zombie), 10),
            StatusOpcodeClass::Noop
        );
        assert_eq!(
            classify_status(TrackedKind::Type(E::Guardian), 21),
            StatusOpcodeClass::GuardianAttackSound
        );
        assert_eq!(
            classify_status(TrackedKind::Type(E::MinecartSpawner), 1),
            StatusOpcodeClass::MobSpawnerDelay
        );
        assert_eq!(
            classify_status(TrackedKind::Player, 22),
            StatusOpcodeClass::PlayerReducedDebug
        );
        assert_eq!(
            classify_status(TrackedKind::Type(E::Wolf), 23),
            StatusOpcodeClass::Noop
        );

        // The full Java override inventory: every family-specific byte has a distinct class,
        // even where several classes share a numeric opcode.
        for (kind, opcode, class) in [
            (
                TrackedKind::Type(E::Wolf),
                6,
                StatusOpcodeClass::TameFailure,
            ),
            (
                TrackedKind::Type(E::Wolf),
                7,
                StatusOpcodeClass::TameSuccess,
            ),
            (
                TrackedKind::Type(E::EntityHorse),
                6,
                StatusOpcodeClass::HorseTameFailure,
            ),
            (
                TrackedKind::Type(E::EntityHorse),
                7,
                StatusOpcodeClass::HorseTameSuccess,
            ),
            (TrackedKind::Type(E::Wolf), 8, StatusOpcodeClass::WolfShake),
            (TrackedKind::Player, 9, StatusOpcodeClass::PlayerFinishUse),
            (
                TrackedKind::Type(E::Villager),
                12,
                StatusOpcodeClass::VillagerHearts,
            ),
            (
                TrackedKind::Type(E::Villager),
                13,
                StatusOpcodeClass::VillagerAngry,
            ),
            (
                TrackedKind::Type(E::Villager),
                14,
                StatusOpcodeClass::VillagerHappy,
            ),
            (
                TrackedKind::Type(E::Witch),
                15,
                StatusOpcodeClass::WitchMagic,
            ),
            (
                TrackedKind::Type(E::Zombie),
                16,
                StatusOpcodeClass::ZombieConversion,
            ),
            (
                TrackedKind::Type(E::FireworksRocketEntity),
                17,
                StatusOpcodeClass::FireworkExplode,
            ),
            (TrackedKind::Type(E::Pig), 18, StatusOpcodeClass::AnimalLove),
            (
                TrackedKind::Type(E::Squid),
                19,
                StatusOpcodeClass::SquidStrokeReset,
            ),
            (
                TrackedKind::Type(E::Zombie),
                20,
                StatusOpcodeClass::LivingExplosion,
            ),
            (
                TrackedKind::Player,
                23,
                StatusOpcodeClass::PlayerNormalDebug,
            ),
        ] {
            assert_eq!(classify_status(kind, opcode), class, "opcode {opcode}");
        }
    }

    /// java: `Entity.ticksExisted` — `ageInTicks` is `ticksExisted + partialTicks`, and it used
    /// to be fed the *client's* global tick counter, identical for every entity in the world, so
    /// every ghast's tentacles and every squid's body moved in lockstep.
    /// java: `EntityRabbit.handleStatusUpdate(1)` starts a ten-tick jump phase. Its inherited
    /// `createRunningParticles` dust needs an underfoot block, which this world-less entry point
    /// and empty world do not have; the live path is pinned by
    /// `rabbit_status_one_emits_inherited_running_dust_but_its_tick_hook_is_empty`. The
    /// wrong-type and missing-id controls protect the entity-polymorphic S19 dispatch.
    #[test]
    fn rabbit_status_one_drives_jump_phase_without_particles() {
        let mut world = World::new();
        let mut tracker = EntityTracker::new();
        spawn_species(&mut tracker, &mut world, 1, EntityType::Rabbit, 0.0);
        spawn_species(&mut tracker, &mut world, 2, EntityType::Pig, 0.0);

        assert!(!tracker.apply_status(2, 1), "status 1 is Rabbit-only");
        assert!(
            !tracker.apply_status(99, 1),
            "an absent entity cannot consume status"
        );
        assert!(tracker.apply_status(1, 1));
        assert_eq!(tracker.get(1).unwrap().rabbit_jump_state(), Some((0, 10)));
        assert_eq!(tracker.get(1).unwrap().render.entity.tail_rotation, 0.0);
        assert!(tracker.take_particle_events().is_empty());

        for expected_ticks in 1..=10 {
            tracker.tick_interpolation(&mut world);
            let rabbit = tracker.get(1).unwrap();
            assert_eq!(rabbit.rabbit_jump_state(), Some((expected_ticks, 10)));
            assert_eq!(
                rabbit.render.entity.tail_rotation,
                expected_ticks as f32 / 10.0
            );
            if expected_ticks == 1 {
                assert_eq!(
                    rabbit.render_params(0.5).entity.tail_rotation,
                    0.15,
                    "ModelRabbit reads the current jump counter plus partialTicks"
                );
            }
            assert!(tracker.take_particle_events().is_empty());
        }

        // Java holds phase 1.0 for the tenth tick, then clears both counters on the next update.
        tracker.tick_interpolation(&mut world);
        let rabbit = tracker.get(1).unwrap();
        assert_eq!(rabbit.rabbit_jump_state(), Some((0, 0)));
        assert_eq!(rabbit.render.entity.tail_rotation, 0.0);
    }

    /// java: `EntityMinecartTNT.handleStatusUpdate(10)` calls `ignite`, which sets an 80-tick
    /// fuse. The remote `onUpdate` decrements it and emits one smoke particle per positive tick;
    /// the client-side `explodeCart` is a no-op, so the zero fuse remains until server removal.
    #[test]
    fn tnt_minecart_status_ten_drives_fuse_and_smoke() {
        let mut world = World::new();
        let mut tracker = EntityTracker::new();
        spawn_species(&mut tracker, &mut world, 1, EntityType::MinecartTNT, 0.0);
        spawn_species(
            &mut tracker,
            &mut world,
            2,
            EntityType::MinecartRideable,
            0.0,
        );

        assert!(
            !tracker.apply_status(2, 10),
            "status 10 is not generic for minecarts"
        );
        assert!(
            !tracker.apply_status(99, 10),
            "an absent entity cannot consume status"
        );
        assert!(tracker.apply_status(1, 10));
        assert_eq!(tracker.get(1).unwrap().tnt_minecart_fuse(), Some(80));
        assert!(tracker.take_particle_events().is_empty());

        tracker.tick_interpolation(&mut world);
        assert_eq!(tracker.get(1).unwrap().tnt_minecart_fuse(), Some(79));
        let smoke = tracker.take_particle_events();
        assert_eq!(smoke.len(), 1);
        assert_eq!(smoke[0].particle_id, SMOKE_NORMAL);
        assert_eq!(smoke[0].position, DVec3::new(0.0, 0.5, 0.0));
        assert_eq!(smoke[0].velocity, DVec3::ZERO);

        for _ in 0..78 {
            tracker.tick_interpolation(&mut world);
            assert_eq!(tracker.take_particle_events().len(), 1);
        }
        assert_eq!(tracker.get(1).unwrap().tnt_minecart_fuse(), Some(1));

        tracker.tick_interpolation(&mut world);
        assert_eq!(tracker.get(1).unwrap().tnt_minecart_fuse(), Some(0));
        assert_eq!(tracker.take_particle_events().len(), 1);
        tracker.tick_interpolation(&mut world);
        assert_eq!(tracker.get(1).unwrap().tnt_minecart_fuse(), Some(0));
        assert!(tracker.take_particle_events().is_empty());
    }

    /// java: `EntityMinecartMobSpawner.handleStatusUpdate(1)` calls
    /// `MobSpawnerBaseLogic.setDelayToMin`, which changes the client delay from its constructor
    /// value of 20 to the default `minSpawnDelay` of 200. The arbitrary-byte and wrong-family
    /// controls keep this status from becoming a generic minecart reset.
    #[test]
    fn mob_spawner_status_one_sets_the_vanilla_minimum_delay() {
        let mut world = World::new();
        let mut tracker = EntityTracker::new();
        spawn_species(
            &mut tracker,
            &mut world,
            1,
            EntityType::MinecartSpawner,
            0.0,
        );
        spawn_species(
            &mut tracker,
            &mut world,
            2,
            EntityType::MinecartRideable,
            0.0,
        );

        assert_eq!(tracker.get(1).unwrap().mob_spawner_delay(), Some(20));
        assert!(
            !tracker.apply_status(2, 1),
            "status 1 is not generic for minecarts"
        );
        assert!(
            !tracker.apply_status(1, 2),
            "the spawner override only accepts status 1"
        );
        assert!(tracker.apply_status(1, 1));
        assert_eq!(tracker.get(1).unwrap().mob_spawner_delay(), Some(200));
        assert!(
            !tracker.apply_status(99, 1),
            "an absent entity cannot consume status"
        );
    }

    /// java: a network-spawned `EntityMinecartMobSpawner` has no entity-NBT/SpawnData packet;
    /// `MobSpawnerBaseLogic.mobID` therefore remains its constructor default `Pig`. Its client
    /// rotation/delay still animate only while `isAnyPlayerWithinRangeAt` is true.
    #[test]
    fn spawner_minecart_exposes_default_pig_and_activation_rotation() {
        let mut world = World::new();
        let mut tracker = EntityTracker::new();
        spawn_species(
            &mut tracker,
            &mut world,
            1,
            EntityType::MinecartSpawner,
            0.0,
        );
        let (entity_id, previous, rotation) = tracker
            .get(1)
            .unwrap()
            .mob_spawner_render_state()
            .expect("spawner render state");
        assert_eq!(entity_id, "Pig");
        assert_eq!(previous, 0.0);
        assert_eq!(rotation, 0.0);

        tracker.tick_interpolation_with_local_player(
            &mut world,
            Some(LocalPlayerTarget {
                position: DVec3::ZERO,
                eye_position: DVec3::new(0.0, 1.62, 0.0),
                spectator: false,
                width: 0.6,
                height: 1.8,
            }),
            &PlayerList::new(),
        );
        let tracked = tracker.get(1).unwrap();
        let (entity_id, previous, rotation) = tracked.mob_spawner_render_state().unwrap();
        assert_eq!(entity_id, "Pig");
        assert_eq!(tracked.mob_spawner_delay(), Some(19));
        assert_eq!(previous, 0.0);
        assert!(
            rotation > 0.0,
            "active spawner carts advance their mob spin"
        );

        let far_away = LocalPlayerTarget {
            position: DVec3::new(100.0, 0.0, 100.0),
            eye_position: DVec3::new(100.0, 1.62, 100.0),
            spectator: false,
            width: 0.6,
            height: 1.8,
        };
        let (before_id, before_previous, before_rotation) = tracker
            .get(1)
            .unwrap()
            .mob_spawner_render_state()
            .map(|(id, previous, rotation)| (id.to_owned(), previous, rotation))
            .unwrap();
        tracker.tick_interpolation_with_local_player(
            &mut world,
            Some(far_away),
            &PlayerList::new(),
        );
        let after = tracker.get(1).unwrap().mob_spawner_render_state().unwrap();
        assert_eq!(after.0, before_id);
        assert_eq!(after.1, before_previous);
        assert_eq!(
            after.2, before_rotation,
            "inactive spawner carts retain rotation"
        );
    }

    /// java: status 17 invokes `WorldClient.makeFireworks` before the rocket's destroy packet;
    /// the resulting `StarterFX` keeps ticking in `EffectRenderer` independently of the entity.
    /// A type-4 burst has 70 sparks followed by one overlay, which gives a useful negative
    /// control against accidentally routing this through the packet particle density gate.
    #[test]
    fn firework_status_seventeen_survives_rocket_despawn_with_full_particles() {
        use mc_nbt::{Nbt, NbtCompound};
        use mc_protocol::{ItemStack, MetadataValue as Wire};

        let mut fireworks = NbtCompound::new();
        let mut explosion = NbtCompound::new();
        explosion.insert("Type", Nbt::Byte(4));
        explosion.insert("Colors", Nbt::IntArray(vec![0x33_66_cc]));
        fireworks.insert("Explosions", Nbt::list(vec![Nbt::Compound(explosion)]));
        let mut root = NbtCompound::new();
        root.insert("Fireworks", Nbt::Compound(fireworks));
        let stack = ItemStack {
            item_id: 401,
            count: 1,
            damage: 0,
            nbt: Some(root),
        };
        let mut metadata = Metadata::new();
        metadata.set(8, mc_world::entity::MetadataValue::ItemStack(Some(stack)));

        let mut world = World::new();
        let mut tracker = EntityTracker::new();
        tracker.spawn(
            &mut world,
            1,
            TrackedKind::Type(EntityType::FireworksRocketEntity),
            None,
            [32, 64 * 32, -32],
            0.0,
            0.0,
            DVec3::new(0.1, 0.2, -0.3),
            metadata,
        );
        tracker.spawn(
            &mut world,
            2,
            TrackedKind::Type(EntityType::Pig),
            None,
            [0, 0, 0],
            0.0,
            0.0,
            DVec3::ZERO,
            Metadata::new(),
        );

        assert!(!tracker.apply_status(2, 17), "status 17 is firework-only");
        assert!(
            !tracker.apply_status(99, 17),
            "an absent entity cannot start a firework"
        );
        assert!(tracker.apply_status(1, 17));
        assert!(tracker.despawn(&mut world, 1));
        tracker.tick_interpolation(&mut world);

        let particles = tracker.take_firework_particles();
        assert_eq!(particles.len(), 71, "70 burst sparks plus one overlay");
        assert!(particles.iter().take(70).all(|particle| {
            matches!(
                particle.kind,
                mc_render::particle::ParticleKind::FireworkSpark { .. }
            )
        }));
        assert!(matches!(
            particles[70].kind,
            mc_render::particle::ParticleKind::FireworkOverlay
        ));
        assert!(particles.iter().all(|particle| {
            particle.pos == DVec3::new(1.0, 64.0, -1.0)
                && particle.color[0] > 0.1
                && particle.color[2] > 0.5
        }));

        let effects = tracker.take_status_effect_events();
        assert_eq!(effects.len(), 1);
        match effects[0] {
            EntityStatusEffectEvent::Sound(sound) => {
                assert_eq!(sound.name, "fireworks.blast");
                assert_eq!(sound.far_name, Some("fireworks.blast_far"));
                assert_eq!(sound.position, Some(DVec3::new(1.0, 64.0, -1.0)));
                assert_eq!(sound.volume, 20.0);
            }
        }

        // Keep this typed-wire import in the test's surface: a subsequent metadata packet uses
        // the same stack shape and must still be accepted by the watcher merge.
        assert!(tracker.apply_metadata(
            &mut world,
            2,
            &vec![mc_protocol::MetadataEntry {
                index: 16,
                value: Wire::Byte(0),
            }],
        ));
    }

    /// java: `EntityFireworkRocket.handleStatusUpdate(17)` reads the rocket's live `posX/Y/Z`,
    /// not the last server target. A rocket advances its ECS position between movement packets,
    /// so this regression keeps the burst at that in-flight position when status 17 arrives.
    #[test]
    fn firework_status_seventeen_captures_live_position_during_interpolation() {
        let mut world = World::new();
        let mut tracker = EntityTracker::new();
        tracker.spawn(
            &mut world,
            1,
            TrackedKind::Type(EntityType::FireworksRocketEntity),
            None,
            [0, 64 * 32, 0],
            0.0,
            0.0,
            DVec3::new(0.25, 0.05, -0.125),
            Metadata::new(),
        );

        let target = tracker.get(1).expect("rocket remains tracked").target_pos;
        tracker.tick_interpolation(&mut world);
        let entity = tracker.get(1).expect("rocket remains tracked").entity;
        let live = world
            .ecs
            .get::<&Position>(entity)
            .expect("rocket has live ECS position")
            .0;
        assert_ne!(
            live, target,
            "the client rocket moved ahead of its packet target"
        );

        assert!(tracker.apply_status_in_world(&world, 1, 17));
        assert_eq!(
            tracker
                .firework_starters
                .last()
                .expect("status 17 creates a starter")
                .position,
            live,
            "StarterFX must use Java's live callback position"
        );
    }

    #[test]
    fn ticks_existed_is_per_entity_and_feeds_age_in_ticks() {
        let mut world = World::new();
        let mut tracker = EntityTracker::new();
        spawn_at(&mut tracker, &mut world, 1, [0, 0, 0]);
        for _ in 0..5 {
            tracker.tick_interpolation(&mut world);
        }
        spawn_at(&mut tracker, &mut world, 2, [0, 0, 0]);
        tracker.tick_interpolation(&mut world);

        assert_eq!(tracker.get(1).unwrap().render.ticks_existed, 6);
        assert_eq!(tracker.get(2).unwrap().render.ticks_existed, 1);
        let p = tracker.get(2).unwrap().render.params(0.5);
        assert!((p.age_in_ticks - 1.5).abs() < 1e-6);
    }

    #[test]
    fn zombie_conversion_metadata_reaches_render_state_but_pig_zombies_stay_plain() {
        let metadata = Metadata::from(vec![(14, mc_world::entity::MetadataValue::Byte(1))]);
        let mut zombie_state = EntityAnimState::default();
        decode_entity_state(
            TrackedKind::Type(EntityType::Zombie),
            &metadata,
            &mut zombie_state,
        );
        assert!(zombie_state.converting);

        let mut pig_zombie_state = EntityAnimState::default();
        decode_entity_state(
            TrackedKind::Type(EntityType::PigZombie),
            &metadata,
            &mut pig_zombie_state,
        );
        assert!(!pig_zombie_state.converting);
    }

    /// `angle_with_bound` is `EntityBodyHelper.computeAngleWithBound`: the *delta* is clamped,
    /// the short way round, and a zero bound pins the result to `from`.
    #[test]
    fn angle_with_bound_clamps_the_delta_not_the_angle() {
        // Inside the bound, `to` comes back unchanged.
        assert!((angle_with_bound(0.0, 20.0, 75.0) - 20.0).abs() < 1e-4);
        // 120 is 120 *past* `from` the short way, so it is pulled back to `from + 75`.
        assert!((angle_with_bound(0.0, 120.0, 75.0) - 75.0).abs() < 1e-4);
        // 200 is -160 the short way, so it is pulled back to `from - 75`, not `+75`. Using the
        // raw difference here instead of the wrapped one would send the head the long way round.
        assert!((angle_with_bound(0.0, 200.0, 75.0) + 75.0).abs() < 1e-4);
        // A zero bound pins the result to `from` exactly — the decayed case a stationary mob
        // reaches after twenty ticks.
        assert!((angle_with_bound(42.0, 0.0, 0.0) - 42.0).abs() < 1e-4);
    }

    /// A stationary remote player starts with Java's zero-valued
    /// `renderYawOffset`, then follows `EntityLivingBase.updateDistance` through
    /// the real tracker tick path.  The packet/ECS yaw and explicit head look
    /// remain independent of the body offset.
    #[test]
    fn remote_player_body_yaw_matches_java_after_120_stationary_ticks() {
        let yaws = [0.0_f32, 45.0, 90.0, 135.0, -180.0, -135.0, -90.0, -45.0];
        let expected = [0.0_f32, 0.0, 42.0, 87.0, -132.0, -87.0, -42.0, 0.0];
        let mut world = World::new();
        let mut tracker = EntityTracker::new();
        let mut players = Vec::new();

        for (index, yaw) in yaws.into_iter().enumerate() {
            let network_id = 100 + index as i32;
            let entity = tracker.spawn(
                &mut world,
                network_id,
                TrackedKind::Player,
                Some(Uuid::nil()),
                [0, 2048, 0],
                yaw,
                0.0,
                DVec3::ZERO,
                Metadata::new(),
            );
            assert_eq!(
                world.ecs.get::<&Rotation>(entity).unwrap().yaw,
                yaw,
                "packet/ECS yaw {yaw}"
            );
            assert_eq!(tracker.get(network_id).unwrap().render.body_yaw, 0.0);
            assert_eq!(tracker.get(network_id).unwrap().render.prev_body_yaw, 0.0);
            assert!(tracker.apply_head_look(network_id, yaw));
            players.push((network_id, entity, yaw, expected[index]));
        }

        // This is the same tick entry used by the client session, without a clock, sleep, GPU,
        // or packet replay.  The empty world keeps the entities stationary.
        for _ in 0..120 {
            tracker.tick_interpolation(&mut world);
        }

        for (network_id, entity, yaw, expected) in players {
            let tracked = tracker.get(network_id).unwrap();
            assert_eq!(tracked.render.body_yaw, expected, "packet yaw {yaw}");
            assert_eq!(
                tracked.render.prev_body_yaw, expected,
                "packet yaw {yaw} previous"
            );
            assert_eq!(tracked.head_yaw, yaw, "packet yaw {yaw} tracked head");
            assert_eq!(tracked.render.head_yaw, yaw, "packet yaw {yaw} render head");
            assert_eq!(
                world.ecs.get::<&Rotation>(entity).unwrap().yaw,
                yaw,
                "packet yaw {yaw} ECS rotation"
            );
        }

        let zombie = tracker.spawn(
            &mut world,
            200,
            TrackedKind::Type(EntityType::Zombie),
            None,
            [0, 2048, 0],
            135.0,
            0.0,
            DVec3::ZERO,
            Metadata::new(),
        );
        assert_eq!(tracker.get(200).unwrap().render.body_yaw, 135.0);
        assert_eq!(world.ecs.get::<&Rotation>(zombie).unwrap().yaw, 135.0);
    }

    // -----------------------------------------------------------------------------------------
    // W-ENTITYTICK — the per-species `onLivingUpdate` layer
    // -----------------------------------------------------------------------------------------

    fn spawn_species(
        tracker: &mut EntityTracker,
        world: &mut World,
        id: i32,
        t: EntityType,
        yaw: f32,
    ) {
        tracker.spawn(
            world,
            id,
            TrackedKind::Type(t),
            None,
            [0, 0, 0],
            yaw,
            0.0,
            DVec3::ZERO,
            Metadata::new(),
        );
    }

    /// java: `EntityBat.onUpdate` (`:120-124`) zeroes every motion component and snaps a roosting
    /// bat's feet to the block ceiling after the inherited living tick. The watcher/model bit is
    /// checked alongside the motion result so a same-tick metadata edge cannot be lost.
    #[test]
    fn a_remote_hanging_bat_zeroes_motion_and_snaps_to_its_ceiling_height() {
        let mut world = World::new();
        let mut tracker = EntityTracker::new();
        let initial_y = 111.0 / FIXED_POINT_SCALE;
        tracker.spawn(
            &mut world,
            1,
            TrackedKind::Type(EntityType::Bat),
            None,
            [0, 111, 0],
            0.0,
            0.0,
            DVec3::new(0.125, -0.25, 0.0625),
            Metadata::new(),
        );
        set_meta(
            &mut tracker,
            &mut world,
            1,
            16,
            mc_protocol::MetadataValue::Byte(1),
        );

        tracker.tick_interpolation(&mut world);

        let tracked = tracker.get(1).expect("bat generation");
        let expected_y = f64::from(floor_f64(initial_y)) + 1.0 - f64::from(tracked.dimensions().1);
        let position = world.ecs.get::<&Position>(tracked.entity).unwrap().0;
        assert_eq!(position, DVec3::new(0.0, expected_y, 0.0));
        assert_eq!(
            world.ecs.get::<&Velocity>(tracked.entity).unwrap().0,
            DVec3::ZERO
        );
        assert!(
            tracked.render.entity.bat_hanging,
            "the roosting watcher bit still reaches ModelBat"
        );
    }

    /// java: a flying bat's own tail applies the exact `0.6000000238418579D` vertical multiplier
    /// after `EntityLivingBase`'s ordinary remote 0.98 pass; X/Z must retain only that inherited
    /// pass.
