    #[test]
    fn chunk_despawn_uses_negative_floor_position_and_cleans_both_mount_directions() {
        use mc_protocol::play::s2c::{AttachType, EntityAttach};

        let mut world = World::new();
        let mut tracker = EntityTracker::new();
        // Fixed-point -1 is -0.03125 blocks: flooring must put it in block/chunk -1, not zero.
        spawn_at(&mut tracker, &mut world, 1, [-1, 0, -1]); // removed vehicle
        spawn_at(&mut tracker, &mut world, 2, [0, 0, 0]); // surviving rider
        spawn_at(&mut tracker, &mut world, 3, [0, 0, 0]); // surviving vehicle
        spawn_at(&mut tracker, &mut world, 4, [-1, 0, -1]); // removed rider
        spawn_at(&mut tracker, &mut world, 5, [-513, 0, -513]); // unrelated column
        assert!(tracker.apply_entity_attach(
            &mut world,
            &EntityAttach {
                entity_id: 2,
                vehicle_entity_id: 1,
                attach_type: AttachType::Vehicle,
            },
        ));
        assert!(tracker.apply_entity_attach(
            &mut world,
            &EntityAttach {
                entity_id: 4,
                vehicle_entity_id: 3,
                attach_type: AttachType::Vehicle,
            },
        ));
        let removed_vehicle = tracker.get(1).expect("removed vehicle").entity;
        let removed_rider = tracker.get(4).expect("removed rider").entity;

        assert_eq!(
            tracker.despawn_in_chunk(&mut world, ChunkPos::new(-1, -1)),
            vec![1, 4]
        );
        assert_eq!(tracker.get(2).expect("surviving rider").riding_entity, None);
        assert_eq!(tracker.get(3).expect("surviving vehicle").ridden_by, None);
        assert!(tracker.get(5).is_some(), "another negative column survives");
        assert!(world.ecs.get::<&Position>(removed_vehicle).is_err());
        assert!(world.ecs.get::<&Position>(removed_rider).is_err());
    }

    #[test]
    fn local_attack_applies_vehicle_impulse_and_rejects_a_reused_target_kind() {
        let mut world = World::new();
        let mut tracker = EntityTracker::new();
        let boat = tracker.spawn(
            &mut world,
            80,
            TrackedKind::Type(EntityType::Boat),
            None,
            [0, 0, 0],
            0.0,
            0.0,
            DVec3::ZERO,
            Metadata::new(),
        );
        assert!(tracker.apply_local_target_attack(
            &mut world,
            80,
            Some(EntityType::Boat),
            0.0,
            0.0,
            0,
            true,
        ));
        assert_eq!(
            world.ecs.get::<&Velocity>(boat).unwrap().0,
            DVec3::new(0.0, 0.1, 0.5)
        );

        // A stale picker classification cannot mutate an id-reused target.  This is the
        // generation/ownership negative for the session -> tracker handoff.
        let before = world.ecs.get::<&Velocity>(boat).unwrap().0;
        assert!(!tracker.apply_local_target_attack(
            &mut world,
            80,
            Some(EntityType::MinecartRideable),
            0.0,
            0.0,
            0,
            true,
        ));
        assert_eq!(world.ecs.get::<&Velocity>(boat).unwrap().0, before);
    }

