    #[test]
    fn crit_animation_is_three_updates_of_sixteen_attempts_and_has_negative_controls() {
        let mut world = World::new();
        let mut tracker = EntityTracker::new();
        tracker.spawn(
            &mut world,
            83,
            TrackedKind::Type(EntityType::Zombie),
            None,
            [0, 20 * 32, 0],
            0.0,
            0.0,
            DVec3::ZERO,
            Metadata::new(),
        );

        assert!(!tracker.apply_crit_animation(&world, 83, 3));
        assert!(tracker.take_particle_events().is_empty());
        assert!(!tracker.apply_crit_animation(&world, 999, 4));
        assert!(tracker.take_particle_events().is_empty());
        assert!(tracker.apply_crit_animation(&world, 83, 4));
        assert_eq!(tracker.crit_emitters.len(), 1);
        let first = tracker.take_particle_events();
        assert!(first.len() <= 16);
        assert!(first.iter().all(|event| event.particle_id == CRIT));

        tracker.tick_interpolation(&mut world);
        assert_eq!(tracker.crit_emitters.len(), 1);
        let second = tracker.take_particle_events();
        assert!(second.len() <= 16);
        assert!(second.iter().all(|event| event.particle_id == CRIT));

        tracker.tick_interpolation(&mut world);
        assert!(tracker.crit_emitters.is_empty());
        let third = tracker.take_particle_events();
        assert!(third.len() <= 16);
        assert!(third.iter().all(|event| event.particle_id == CRIT));
        tracker.tick_interpolation(&mut world);
        assert!(tracker.take_particle_events().is_empty());

        // Type 5 selects the magic recolour id and still owns a fresh three-update emitter.
        assert!(tracker.apply_crit_animation(&world, 83, 5));
        assert!(tracker
            .take_particle_events()
            .iter()
            .all(|event| event.particle_id == mc_render::particle::packet::CRIT_MAGIC));
    }

    #[test]
    fn local_crit_animation_uses_session_geometry_without_creating_a_remote_entry() {
        let mut world = World::new();
        let mut tracker = EntityTracker::new();
        let local = LocalPlayerTarget {
            position: DVec3::new(7.0, 20.0, -3.0),
            eye_position: DVec3::new(7.0, 21.62, -3.0),
            spectator: false,
            width: 0.6,
            height: 1.8,
        };
        assert!(tracker.apply_local_crit_animation(local, 5));
        let first = tracker.take_particle_events();
        assert!(first.len() <= 16);
        assert!(first.iter().all(|event| {
            event.particle_id == mc_render::particle::packet::CRIT_MAGIC
                && (event.position.x - local.position.x).abs() <= 0.15
                && (event.position.z - local.position.z).abs() <= 0.15
        }));
        assert!(
            tracker.get(0).is_none(),
            "local player stays out of remote index"
        );

        tracker.tick_interpolation_with_local_player(&mut world, Some(local), &PlayerList::new());
        assert_eq!(tracker.local_crit_emitters.len(), 1);
        assert!(tracker
            .take_particle_events()
            .iter()
            .all(|event| event.particle_id == mc_render::particle::packet::CRIT_MAGIC));
        tracker.tick_interpolation_with_local_player(&mut world, Some(local), &PlayerList::new());
        assert!(tracker.local_crit_emitters.is_empty());
        assert!(tracker
            .take_particle_events()
            .iter()
            .all(|event| event.particle_id == mc_render::particle::packet::CRIT_MAGIC));
    }

    #[test]
    fn seeded_trackers_match_spawn_status_and_firework_streams() {
        let mut world_a = World::new();
        let mut world_b = World::new();
        let mut a = EntityTracker::with_random_seed(0x5EED);
        let mut b = EntityTracker::with_random_seed(0x5EED);

        for tracker_world in [(&mut a, &mut world_a), (&mut b, &mut world_b)] {
            tracker_world.0.spawn(
                tracker_world.1,
                1,
                TrackedKind::Type(EntityType::Item),
                None,
                [0, 0, 0],
                0.0,
                0.0,
                DVec3::ZERO,
                Metadata::new(),
            );
        }
        assert_eq!(
            a.get(1).unwrap().particle_random.raw_seed(),
            b.get(1).unwrap().particle_random.raw_seed()
        );
        assert_eq!(
            a.get(1).unwrap().dropped_item_hover_start.to_bits(),
            b.get(1).unwrap().dropped_item_hover_start.to_bits()
        );

        for tracker_world in [(&mut a, &mut world_a), (&mut b, &mut world_b)] {
            tracker_world.0.spawn(
                tracker_world.1,
                2,
                zombie(),
                None,
                [0, 0, 0],
                0.0,
                0.0,
                DVec3::ZERO,
                Metadata::new(),
            );
        }
        assert!(a.apply_crit_animation(&world_a, 2, 4));
        assert!(b.apply_crit_animation(&world_b, 2, 4));
        assert_eq!(a.take_particle_events(), b.take_particle_events());
        assert_eq!(
            a.crit_emitters[0].random.raw_seed(),
            b.crit_emitters[0].random.raw_seed()
        );

        for tracker_world in [(&mut a, &mut world_a), (&mut b, &mut world_b)] {
            tracker_world.0.spawn(
                tracker_world.1,
                3,
                TrackedKind::Type(EntityType::FireworksRocketEntity),
                None,
                [0, 0, 0],
                0.0,
                0.0,
                DVec3::ZERO,
                Metadata::new(),
            );
        }
        assert!(a.apply_status(3, 17));
        assert!(b.apply_status(3, 17));
        assert_eq!(
            a.firework_starters[0].random.raw_seed(),
            b.firework_starters[0].random.raw_seed()
        );
        assert_eq!(
            a.firework_starters[0]
                .effect_random
                .as_ref()
                .unwrap()
                .raw_seed(),
            b.firework_starters[0]
                .effect_random
                .as_ref()
                .unwrap()
                .raw_seed()
        );

        a.tick_interpolation(&mut world_a);
        b.tick_interpolation(&mut world_b);
        assert_eq!(a.take_firework_particles(), b.take_firework_particles());
    }

